        assert_eq!(app.sharing_rows()[1], SharingRow::GetKey);
        assert_eq!(app.ctx().sharing_enter_word, "copy");
        app.opener = Some("open".into());
        assert_eq!(app.ctx().sharing_enter_word, "open");
