    #[test]
    fn column_agent_settings_return_to_parent_and_offers_cycle_on_the_wire() {
        use mesimon_core::board::ColumnOffers;
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        press(&mut app, 'k');
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        let door = keymap::column_items(&app.ctx())
            .iter()
            .position(|m| m.verb == Verb::ColumnAgentBehaviour)
            .unwrap();
        if let Mode::ColumnSettings { idx, .. } = &mut app.mode {
            *idx = door;
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(app.column_agents);
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(
            app.board.column("todo").unwrap().settings.claude_mode,
            mesimon_core::board::ClaudeMode::Auto
        );
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert!(!app.column_agents);
        assert!(matches!(app.mode, Mode::ColumnSettings { idx, .. } if idx == door));
        let row = keymap::column_items(&app.ctx())
            .iter()
            .position(|m| m.verb == Verb::ColumnReclaim)
            .unwrap();
        if let Mode::ColumnSettings { idx, .. } = &mut app.mode {
            *idx = row;
        }
        for offer in
            [ColumnOffers::Sleep, ColumnOffers::Archive, ColumnOffers::Both, ColumnOffers::Off]
        {
            app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
            assert_eq!(app.board.column("todo").unwrap().settings.offers(), offer);
            assert_eq!(app.ctx().col_offers_word, offer.word());
        }
        assert!(sent_contains(&sent, "SetColumnSettings"));
    }

    /// T-543: the column's idle park is a row in Agent behaviour that
    /// cycles its minutes on the wire and is not offered on a board where
    /// no Claude would hear it.
    #[test]
    fn column_sleep_cycles_on_the_wire() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        press(&mut app, 'k');
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        app.column_agents = true;
        let row = |app: &App| {
            keymap::column_items(&app.ctx()).into_iter().find(|m| m.verb == Verb::ColumnSleepAfter)
        };
        assert_eq!((row(&app).unwrap().label)(&app.ctx()), "Sleep idle agents: off");
        let idx = keymap::column_items(&app.ctx())
            .iter()
            .position(|m| m.verb == Verb::ColumnSleepAfter)
            .unwrap();
        if let Mode::ColumnSettings { idx: i, .. } = &mut app.mode {
            *i = idx;
        }
        for minutes in [1, 5, 15, 60, 0] {
            app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
            assert_eq!(app.board.column("todo").unwrap().settings.sleep_after_minutes, minutes);
            assert_eq!(app.ctx().col_sleep_after, minutes);
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!((row(&app).unwrap().label)(&app.ctx()), "Sleep idle agents after 1 min");
        assert_eq!(sent.borrow().iter().filter(|r| r.contains("SetColumnSettings")).count(), 6);
        app.board_mut().agent_provider = mesimon_core::board::AgentProvider::Codex;
        assert!(row(&app).is_none(), "nothing parks a Codex agent here");
    }

    /// The OS flipped (T-485): the watch's channel says so, and the board
    /// rests on the other slot's pick with a full repaint. Nothing was
    /// typed anywhere — the whole point of the road.
    #[test]
    fn an_os_flip_moves_the_board_to_the_other_slot() {
        let mut app = app_three_columns();
        let (watch, tx) = crate::appearance::Watch::seeded();
        app.appearance = Some(watch);
        app.follow_appearance();
        assert_eq!(app.theme.flavor, Flavor::Graphite, "no answer, no repaint");
        tx.send(Ground::Light).unwrap();
        app.force_redraw = false;
        app.follow_appearance();
        assert_eq!(app.ground, Ground::Light);
        assert_eq!(app.theme.flavor, Flavor::Chalk, "the light slot's pick");
        assert!(app.force_redraw, "a retheme repaints from nothing");
        // The same answer again is nothing.
        tx.send(Ground::Light).unwrap();
        app.force_redraw = false;
        app.follow_appearance();
        assert!(!app.force_redraw);
        // Under the picker the board still follows the ground (T-717: the
        // preview is the picker's own), and the picker keeps its slot.
        open_theme_picker(&mut app);
        assert_eq!(app.mode, Mode::Theme { idx: 1, slot: Slot::Both });
        press(&mut app, 'j');
        assert_eq!(app.theme.flavor, Flavor::Chalk, "browsing repaints only the preview");
        assert_eq!(app.theme_preview(2, Slot::Both), Flavor::Blue);
        tx.send(Ground::Dark).unwrap();
        app.follow_appearance();
        assert_eq!(app.theme.flavor, Flavor::Graphite, "the board rests on the dark slot's pick");
        assert_eq!(app.mode, Mode::Theme { idx: 2, slot: Slot::Both }, "the picker keeps its slot");
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Sections);
    }

    /// Tab in the picker (T-485) cycles the state a pick is for: both,
    /// where it opens (T-625), the board's own ground, the other, and round
    /// again. Landing on a
    /// ground shows that ground's saved pick; Enter saves for the state
    /// shown, and the ground itself never moves.
    #[test]
    fn tab_cycles_the_state_a_pick_is_for() {
        let dir = std::env::temp_dir().join(format!("msmn-app-slot-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let path = dir.join("prefs.json");
        let mut app = app_three_columns();
        app.prefs_path = Some(path.clone());
        app.seed_pref(|p| p.set(Ground::Light, Flavor::Blue));
        open_theme_picker(&mut app);
        assert_eq!(app.mode, Mode::Theme { idx: 0, slot: Slot::Both });
        assert_eq!(app.ctx().theme_tab_word, "dark", "the hint names the next stop");
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Theme { idx: 0, slot: Slot::One(Ground::Dark) });
        assert_eq!(app.ctx().theme_tab_word, "light");
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Theme { idx: 2, slot: Slot::One(Ground::Light) }, "on blue");
        assert_eq!(app.theme_preview(2, Slot::One(Ground::Light)), Flavor::Blue);
        assert_eq!(app.theme.flavor, Flavor::Graphite, "the board keeps its own");
        assert_eq!(app.ctx().theme_tab_word, "both");
        press(&mut app, 'j');
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.status, "amber saved for light terminals");
        assert_eq!(app.ground, Ground::Dark, "a pick never moves the ground");
        assert_eq!(app.theme.flavor, Flavor::Graphite, "the board rests on its own state");
        assert_eq!(app.prefs.light, Flavor::Amber);
        assert_eq!(app.prefs.dark, Flavor::Graphite);
        assert_eq!(app.mode, Mode::Theme { idx: 3, slot: Slot::One(Ground::Light) }, "it stays");
        // Both: the cursor stays where it is, and Enter writes both slots.
        // (Back to the section list and into the page again.)
        let reopen = |app: &mut App| {
            app.mode = Mode::Sections;
            app.settings_section = keymap::SettingsSection::Theme;
            app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        };
        reopen(&mut app);
        for _ in 0..3 {
            app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        }
        assert_eq!(app.mode, Mode::Theme { idx: 3, slot: Slot::Both }, "the cursor stays on amber");
        assert_eq!(app.ctx().theme_tab_word, "dark", "and round again");
        press(&mut app, 'k');
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.status, "blue saved for dark and light terminals");
        assert_eq!((app.prefs.dark, app.prefs.light), (Flavor::Blue, Flavor::Blue));
        assert_eq!(app.theme.flavor, Flavor::Blue);
        let back = crate::prefs::load(&path).prefs;
        assert_eq!((back.dark, back.light), (Flavor::Blue, Flavor::Blue));
        // Both → current.
        reopen(&mut app);
        assert_eq!(app.mode, Mode::Theme { idx: 2, slot: Slot::Both });
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Theme { idx: 2, slot: Slot::One(Ground::Dark) });
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        // Board scope: Tab to the other state opens on inherit when the
        // board has no pick there; both + inherit clears both keys.
        let board = dir.join("board.json");
        app.board_prefs_path = Some(board.clone());
        app.settings_board_scope = true;
        app.board_prefs.set_flavor(Ground::Dark, Flavor::Amber);
        app.resolve_prefs();
        reopen(&mut app);
        assert_eq!(app.mode, Mode::Theme { idx: 4, slot: Slot::Both }, "the board's");
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Theme { idx: 0, slot: Slot::One(Ground::Light) }, "inherit");
        assert_eq!(
            app.theme_preview(0, Slot::One(Ground::Light)),
            Flavor::Blue,
            "inherit previews the machine's light pick"
        );
        app.mode = Mode::Theme { idx: 3, slot: Slot::One(Ground::Light) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.board_prefs.flavor(Ground::Light), Some(Flavor::Blue));
        assert_eq!(app.board_prefs.flavor(Ground::Dark), Some(Flavor::Amber), "untouched");
        reopen(&mut app);
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        app.mode = Mode::Theme { idx: 0, slot: Slot::Both };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.status, "both themes inherit the machine's ∙ saved for this board");
        assert_eq!(app.board_prefs.flavor(Ground::Dark), None);
        assert_eq!(app.board_prefs.flavor(Ground::Light), None);
        assert_eq!(app.machine_prefs.light, Flavor::Blue, "the machine's is untouched");
    }

    fn says_light() -> Option<Ground> {
        Some(Ground::Light)
    }

    fn says_nothing() -> Option<Ground> {
        None
    }

    /// The OS is followed exactly while the two slots differ (T-625): the
    /// watch runs then, unpinned and with a probe. Arming asks once and
    /// moves the board on the answer; no answer is reported as barred.
    #[test]
    fn the_watch_runs_while_the_slots_differ() {
        let mut app = app_three_columns();
        app.seed_pref(|p| p.light = p.dark);
        // No probe (every test app): nothing runs whatever the slots say.
        app.arm_appearance();
        assert!(app.appearance.is_none());
        // One theme for both: a probe is not even asked.
        app.appearance_probe = Some(says_light);
        app.arm_appearance();
        assert!(app.appearance.is_none(), "nothing to follow");
        assert_eq!(app.ground, Ground::Dark);
        // Two themes: arming moves the board to the light slot.
        app.set_pref("chalk for light terminals", |p| p.light = Flavor::Chalk);
        assert!(app.appearance.is_some());
        assert_eq!(app.ground, Ground::Light);
        assert_eq!(app.theme.flavor, Flavor::Chalk);
        assert!(!app.ctx().theme_os_barred);
        let detail = keymap::theme_detail(&app.ctx());
        assert!(detail.ends_with("follows the OS"), "{detail}");
        // One again: the thread's handle goes; the ground stays where it is.
        app.set_pref("graphite for light terminals", |p| p.light = Flavor::Graphite);
        assert!(app.appearance.is_none());
        assert_eq!(app.ground, Ground::Light);
        assert!(keymap::theme_detail(&app.ctx()).contains("for dark and light terminals"));
        // A pin keeps the watch down; the pick that clears the pin arms it.
        app.forced = Some(Flavor::Green);
        app.set_pref("chalk for light terminals", |p| p.light = Flavor::Chalk);
        assert!(app.appearance.is_none(), "pinned");
        open_theme_picker(&mut app);
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap(); // the light slot alone
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(app.forced.is_none());
        assert!(app.appearance.is_some(), "the pick lifted the pin and the watch is up");
        // An OS that does not answer: barred, and the Theme row says so.
        app.appearance = None;
        app.appearance_probe = Some(says_nothing);
        app.arm_appearance();
        assert!(app.appearance.is_some(), "the thread still asks, in case it starts answering");
        assert!(app.ctx().theme_os_barred);
        let detail = keymap::theme_detail(&app.ctx());
        assert!(detail.contains("did not say"), "{detail}");
    }

