    /// Worktree follow-ups also offer Queue/Steer.
    #[test]
    fn the_ask_toggle_can_steer_a_worktree_ticket() {
        let (mut app, _sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        app.board_mut().tickets[0].workspace = Some(WorkspaceStrategy::Worktree);
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_queueable);
        assert!(app.ctx().ask_queued);
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(!app.ctx().ask_queued, "the key selects steer");
        assert!(matches!(
            app.mode,
            Mode::Input { purpose: InputPurpose::Prompt { queued: false, .. }, .. }
        ));
    }

    /// T-420: on a card whose agent sits on its plan dialog, Shift+Enter
    /// opens the field at `accept plan`, a blank Enter sends the accept —
    /// a `PromptSession` with the flag and no words — and the status says
    /// what the card will: `accepting plan`. Shift+Tab does nothing there:
    /// on the dialog the field has one stop, and `queued` beside a dialog
    /// would read as a choice that is not one.
    #[test]
    fn shift_enter_on_a_ready_plan_accepts_it_and_shift_tab_is_inert() {
        use mesimon_core::board::Reason;
        let (mut app, sent, _) =
            app_with_claude(SessionState::RequiresAction { reason: Reason::Plan }, false);
        app.rich_keys = true;
        assert!(app.ctx().ticket_plan_ready);
        assert!(!app.ctx().ticket_planning);
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Board, Verb::Prompt, &app.ctx()),
            Some(("shift+enter", "accept plan + ask"))
        );
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(matches!(
            app.mode,
            Mode::Input {
                purpose: InputPurpose::Prompt { queued: true, accept_plan: true, .. },
                ..
            }
        ));
        assert!(app.ctx().ask_accepts_plan);
        assert!(app.ctx().ask_plan_able);
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Input, Verb::Save, &app.ctx()),
            Some(("enter", "accept plan"))
        );
        // One stop: Shift+Tab is unbound and unhinted here.
        assert!(app.ctx().ask_plan_ready);
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Input, Verb::CycleWorkspace, &app.ctx()),
            None
        );
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_queued && app.ctx().ask_accepts_plan);
        // A blank Enter is the accept itself.
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(sent_contains(&sent, "accept_plan: true"), "{:?}", sent.borrow());
        assert!(sent_contains(&sent, "text: \"\""), "{:?}", sent.borrow());
        assert_eq!(app.status, "accepting plan");
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("accepting plan"));
        // Reopened, the field carries the flag back.
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_accepts_plan);
    }

    /// T-429: a column holding a seat on its plan dialog opens its field at
    /// `accept plan` — the single ask's rule, plural — and a blank Enter
    /// sends ONE `PromptColumn` with the flag; the status counts the seats
    /// parked with it. Shift+Tab keeps its ring there (the other seats can
    /// still take words now or queued), so the dialog's one-stop rule is
    /// the card's alone.
    #[test]
    fn shift_enter_on_a_header_over_a_ready_plan_accepts_every_plan() {
        use mesimon_core::board::Reason;
        let (mut app, sent, _) =
            app_with_claude(SessionState::RequiresAction { reason: Reason::Plan }, false);
        app.rich_keys = true;
        press(&mut app, 'k');
        assert!(app.on_column_header());
        assert!(app.ctx().col_plan_able);
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Board, Verb::Prompt, &app.ctx()),
            Some(("shift+enter", "accept plans + ask"))
        );
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(matches!(
            &app.mode,
            Mode::Input {
                purpose: InputPurpose::Prompt {
                    target: AskTarget::Column(n),
                    queued: true,
                    immediately: false,
                    accept_plan: true,
                    ..
                },
                ..
            } if n == "todo"
        ));
        assert!(app.ctx().ask_accepts_plan && app.ctx().ask_plan_able);
        assert!(!app.ctx().ask_plan_ready, "a column is never on ONE dialog");
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Input, Verb::Save, &app.ctx()),
            Some(("enter", "accept plan"))
        );
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Input, Verb::CycleWorkspace, &app.ctx()),
            Some(("shift+tab", "accept plan / queued / now"))
        );
        // The ring walks on and comes back.
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_queued && !app.ctx().ask_accepts_plan);
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(!app.ctx().ask_queued && !app.ctx().ask_accepts_plan);
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_queued && app.ctx().ask_accepts_plan);
        // A blank Enter is the accept, for every plan-able seat.
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(sent_contains(&sent, "PromptColumn"), "{:?}", sent.borrow());
        assert!(sent_contains(&sent, "accept_plan: true"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "PromptSession"), "one command, not one per seat");
        // Ticket 1 is on its dialog; ticket 2's seat is empty and takes the
        // blank as a start (T-405), parked behind the shared checkout.
        assert_eq!(app.status, "accepts plan 1 ∙ queued 1");
        assert!(app.on_column_header(), "the cursor stayed on the header");
    }

    /// T-429: the flagged row names what its press waits on — the tickets
    /// working in its checkout — and `accepting plan` is only ever the
    /// press that goes next.
    #[test]
    fn the_accept_row_names_the_ticket_it_waits_on() {
        use mesimon_core::board::Reason;
        let (mut app, _, _) =
            app_with_claude(SessionState::RequiresAction { reason: Reason::Plan }, false);
        let row = |app: &mut App, waits_on: Vec<String>| {
            app.pending = vec![mesimon_core::command::Pending {
                ticket: ulid::Ulid(1),
                action: mesimon_core::command::PendingAction::Ask,
                waits_on,
                asking: Vec::new(),
                text: None,
                in_flight: false,
                by: None,
                sends: false,
                accept_plan: true,
                plan: false,
                held: None,
                deliver: mesimon_core::command::Deliver::Idle,
            }];
            app.pending_row(ulid::Ulid(1))
        };
        assert_eq!(row(&mut app, vec![]).as_deref(), Some("accepting plan"));
        // Its own press in flight lists itself, and that is `accepting`.
        assert_eq!(row(&mut app, vec!["T-1".into()]).as_deref(), Some("accepting plan"));
        assert_eq!(row(&mut app, vec!["T-3".into()]).as_deref(), Some("accepts plan ∙ after T-3"));
        assert_eq!(
            row(&mut app, vec!["T-3".into(), "T-4".into()]).as_deref(),
            Some("accepts plan ∙ after T-3 +1")
        );
    }

    /// T-434: `^p` in the ask field arms plan mode for the launch the words
    /// end in. On an EMPTY seat the start carries the flag; the row under
    /// the field says `now ∙ plan mode`; the receipt and the card say it;
    /// and a seat the key cannot serve — a working claude, one already
    /// planning — offers no key.
    #[test]
    fn ctrl_p_in_the_ask_field_starts_the_agent_in_plan_mode() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        app.rich_keys = true;
        // An empty seat: the field opens, `^p` is offered and flips.
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().prompting && app.ctx().plan_able && !app.ctx().plan_armed);
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Input, Verb::PlanMode, &app.ctx()),
            Some(("^p", "plan mode"))
        );
        app.handle_key(KeyCode::Char('p'), KeyModifiers::CONTROL).unwrap();
        assert!(app.ctx().plan_armed);
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Input, Verb::PlanMode, &app.ctx()),
            Some(("^p", "plan mode off"))
        );
        assert_eq!(App::ask_mode_word(false, false, false, true), "now ∙ plan mode");
        assert_eq!(App::ask_mode_word(false, true, false, true), "queued ∙ plan mode");
        // A second press takes it off, a third puts it back; then send.
        app.handle_key(KeyCode::Char('p'), KeyModifiers::CONTROL).unwrap();
        assert!(!app.ctx().plan_armed);
        app.handle_key(KeyCode::Char('p'), KeyModifiers::CONTROL).unwrap();
        for ch in "scope it".chars() {
            app.handle_key(KeyCode::Char(ch), KeyModifiers::NONE).unwrap();
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(sent_contains(&sent, "plan: true"), "{:?}", sent.borrow());
        assert_eq!(app.status, "agent started in plan mode ∙ asked");
        // The fake daemon launched it with the flag, so the seat now reads
        // as planning (T-420) and the next field opens at `accept plan`,
        // with no `^p` — the flag is about the NEXT launch, and there is
        // none to make.
        assert!(app.ticket_planning(ulid::Ulid(1)));
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_accepts_plan && !app.ctx().plan_able);
        assert_eq!(mesimon_core::keymap::hint_for(Scope::Input, Verb::PlanMode, &app.ctx()), None);
    }

    /// T-434: on a live claude the key is offered only between turns — a
    /// working one has no launch to flag — and the send is a park-and-wake
    /// the receipt names; queued, the card says `queued ∙ plan mode`. The
    /// flag rides the grown room and folds back with it.
    #[test]
    fn ctrl_p_on_an_idle_pane_restarts_it_in_plan_mode_and_a_working_one_offers_nothing() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().prompting && !app.ctx().plan_able);
        assert_eq!(mesimon_core::keymap::hint_for(Scope::Input, Verb::PlanMode, &app.ctx()), None);
        // Inert: the press is not a verb here, and the flag stays off.
        app.handle_key(KeyCode::Char('p'), KeyModifiers::CONTROL).unwrap();
        assert!(!app.ctx().plan_armed);
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();

        app.board_mut().sessions[0].state =
            SessionState::Idle { stop_reason: mesimon_core::board::StopReason::EndTurn };
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().plan_able);
        app.handle_key(KeyCode::Char('p'), KeyModifiers::CONTROL).unwrap();
        assert!(app.ctx().plan_armed);
        // Into the room and back: the flag rides along both ways.
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        assert!(matches!(app.mode, Mode::Editor(_)) && app.ctx().plan_armed);
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Editor, Verb::PlanMode, &app.ctx()),
            Some(("^p", "plan mode off"))
        );
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert!(matches!(app.mode, Mode::Input { .. }) && app.ctx().plan_armed);
        // Queued: the card's row wears the mode.
        if !app.ctx().ask_queued {
            app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        }
        assert!(app.ctx().ask_queued);
        for ch in "later".chars() {
            app.handle_key(KeyCode::Char(ch), KeyModifiers::NONE).unwrap();
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "plan: true"), "{:?}", sent.borrow());
        assert!(app.status.starts_with("agent restarts in plan mode"), "{}", app.status);
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("queued ∙ plan mode"));
        // Reopened on the waiting words, the flag comes back with them.
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().plan_armed && app.ctx().ask_queued);
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();

        // Sent now on the idle pane: a park and a wake, said as such. (The
        // refresh after the send re-read the fake board's own record, so
        // the idle is set again.)
        app.pending.clear();
        app.board_mut().sessions[0].state =
            SessionState::Idle { stop_reason: mesimon_core::board::StopReason::EndTurn };
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        if app.ctx().ask_queued {
            app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        }
        assert!(!app.ctx().ask_queued);
        app.handle_key(KeyCode::Char('p'), KeyModifiers::CONTROL).unwrap();
        assert!(app.ctx().plan_armed);
        for ch in "go".chars() {
            app.handle_key(KeyCode::Char(ch), KeyModifiers::NONE).unwrap();
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.status, "restarted agent in plan mode ∙ asked");
    }

    /// T-434: `^p` in the composer — one-line and grown — starts the new
    /// ticket's claude in plan mode on Shift+Enter, and the selector row
    /// says so. A codex board offers no key.
    #[test]
    fn ctrl_p_in_the_composer_starts_the_new_ticket_in_plan_mode() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        app.rich_keys = true;
        app.handle_key(KeyCode::Char('o'), KeyModifiers::NONE).unwrap();
        assert!(app.ctx().composing && app.ctx().plan_able);
        app.handle_key(KeyCode::Char('p'), KeyModifiers::CONTROL).unwrap();
        assert!(app.ctx().plan_armed);
        // Grown and folded, the flag survives.
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        assert!(matches!(
            app.mode,
            Mode::Editor(Editor { purpose: EditorPurpose::Compose { plan: true, .. }, .. })
        ));
        app.handle_key(KeyCode::Char('s'), KeyModifiers::CONTROL).unwrap();
        assert!(matches!(
            app.mode,
            Mode::Input { purpose: InputPurpose::Create { plan: true, .. }, .. }
        ));
        for ch in "plan it".chars() {
            app.handle_key(KeyCode::Char(ch), KeyModifiers::NONE).unwrap();
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(sent_contains(&sent, "submit_prompt: true"), "{:?}", sent.borrow());
        assert!(sent_contains(&sent, "plan: true"), "{:?}", sent.borrow());
        assert_eq!(app.status, "agent started on the title in plan mode");

        let mut codex = app_three_columns();
        codex.board_mut().agent_provider = mesimon_core::board::AgentProvider::Codex;
        codex.handle_key(KeyCode::Char('o'), KeyModifiers::NONE).unwrap();
        assert!(codex.ctx().composing && !codex.ctx().plan_able);
        codex.handle_key(KeyCode::Char('p'), KeyModifiers::CONTROL).unwrap();
        assert!(!codex.ctx().plan_armed);
    }

    /// A seat whose first prompt never went (T-570): the card's row says
    /// so, the hint says `resend`, and Shift+Enter sends the resend — no
    /// field, because the words were decided when the agent was started.
    #[test]
    fn shift_enter_on_an_unsent_seat_resends_without_a_field() {
        let (mut app, sent, _) = app_with_claude(
            SessionState::Idle { stop_reason: mesimon_core::board::StopReason::Unknown },
            false,
        );
        app.rich_keys = true;
        assert!(!app.ctx().ticket_unsent);
        app.board_mut().sessions[0].unsent =
            Some(mesimon_core::board::Unsent { text: String::new(), brief: true });
        assert!(app.ctx().ticket_unsent);
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("brief not sent"));
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Board, Verb::Prompt, &app.ctx()),
            Some(("shift+enter", "resend"))
        );
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(matches!(app.mode, Mode::Normal), "no field opens");
        assert!(sent_contains(&sent, "resend: true"), "{:?}", sent.borrow());
        assert_eq!(app.status, "resending");
    }

    /// T-420: an agent launched in plan mode and still working is KNOWN to
    /// be planning, so the field opens at `accept plan` too — the ring
    /// then has all three stops — and words sent there queue with the
    /// flag: the card says `queued ∙ accepts plan`. A held ask reads
    /// `agent asked ∙ you send`. A session not launched in plan mode opens at
    /// the board's default and has no `accept plan` stop.
    #[test]
    fn a_planning_agent_queues_with_the_flag_and_a_held_ask_says_why() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        assert!(!app.ctx().ticket_planning);
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(!app.ctx().ask_accepts_plan && !app.ctx().ask_plan_able);
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();

        app.board_mut().sessions[0].argv =
            vec!["claude".into(), "--permission-mode".into(), "plan".into()];
        assert!(app.ctx().ticket_planning);
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_accepts_plan);
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Input, Verb::CycleWorkspace, &app.ctx()),
            Some(("shift+tab", "accept plan / queued / now / immediately"))
        );
        // accept plan → queued → now → immediately (T-601) → accept plan.
        let immediately = |app: &App| match &app.mode {
            Mode::Input { purpose: InputPurpose::Prompt { immediately, .. }, .. } => *immediately,
            _ => panic!("the field is up"),
        };
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_queued && !app.ctx().ask_accepts_plan);
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(!app.ctx().ask_queued && !app.ctx().ask_accepts_plan && !immediately(&app));
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(!app.ctx().ask_queued && immediately(&app));
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_queued && app.ctx().ask_accepts_plan && !immediately(&app));
        for ch in "after".chars() {
            app.handle_key(KeyCode::Char(ch), KeyModifiers::NONE).unwrap();
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "accept_plan: true"), "{:?}", sent.borrow());
        assert!(app.status.starts_with("accepts plan ∙ "), "{}", app.status);
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("queued ∙ accepts plan"));

        app.pending = vec![mesimon_core::command::Pending {
            ticket: ulid::Ulid(1),
            action: mesimon_core::command::PendingAction::Ask,
            waits_on: vec![],
            asking: Vec::new(),
            text: Some("after".into()),
            in_flight: false,
            by: None,
            sends: false,
            accept_plan: false,
            held: Some("agent asked".into()),
            plan: false,
            deliver: mesimon_core::command::Deliver::Idle,
        }];
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("agent asked ∙ you send"));
        assert!(app.ctx().ticket_queued, "a held ask is still edited and sent from the board");
        assert!(app.ctx().ticket_held, "and its ^y says send (T-551)");
    }

    /// A waiting ask written in the room (T-380) has lines, and reopens in
    /// the room as it was — a one-line field would flatten it. `^s`
    /// re-queues it, lines and all.
    #[test]
    fn a_queued_ask_with_lines_reopens_in_the_room() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        app.pending = vec![mesimon_core::command::Pending {
            ticket: ulid::Ulid(1),
            action: mesimon_core::command::PendingAction::Ask,
            waits_on: vec!["T-3".into()],
            asking: Vec::new(),
            text: Some("commit it\nthen push".into()),
            in_flight: false,
            by: None,
            sends: false,
            accept_plan: false,
            plan: false,
            held: None,
            deliver: mesimon_core::command::Deliver::Idle,
        }];
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        let ed = editor(&app);
        assert!(ed.asking());
        assert_eq!(ed.body.as_str(), "commit it\nthen push");
        assert!(app.ctx().ask_queued, "still at queued");
        assert!(!ed.dirty());
        app.handle_key(KeyCode::Char('s'), KeyModifiers::CONTROL).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(sent_contains(&sent, "commit it\\nthen push"), "{:?}", sent.borrow());
        assert!(sent_contains(&sent, "queued: true"), "{:?}", sent.borrow());
    }

    /// A ticket with an ask waiting reopens the field on those words, at
    /// `queued`; Esc leaves it waiting, a blank Enter drops it, and sending
    /// now over it says the waiting one went.
    #[test]
    fn a_queued_ask_reopens_prefilled_and_a_blank_enter_drops_it() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        app.client
            .request(Command::SetFollowUpMode { mode: mesimon_core::board::FollowUpMode::Steer })
            .unwrap();
        app.refresh().unwrap();
        app.pending = vec![mesimon_core::command::Pending {
            ticket: ulid::Ulid(1),
            action: mesimon_core::command::PendingAction::Ask,
            waits_on: vec!["T-3".into()],
            asking: Vec::new(),
            text: Some("commit it".into()),
            in_flight: false,
            by: None,
            sends: false,
            accept_plan: false,
            plan: false,
            held: None,
            deliver: mesimon_core::command::Deliver::Idle,
        }];
        assert!(app.ctx().ticket_queued);
        assert_eq!(
            mesimon_core::keymap::hint_for(Scope::Board, Verb::Prompt, &app.ctx()),
            Some(("shift+enter", "edit the queued ask"))
        );
        assert!(app.owed(ulid::Ulid(1)), "the card wears the owed mark");
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("queued ∙ after T-3"));
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert_eq!(field_text(&app), "commit it");
        assert!(app.ctx().ask_queued);
        // Esc: still waiting, nothing sent.
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert!(!sent_contains(&sent, "PromptSession"));
        assert!(!sent_contains(&sent, "DropQueuedAsk"));
        // A blank Enter drops it.
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        for _ in 0.."commit it".len() {
            app.handle_key(KeyCode::Backspace, KeyModifiers::NONE).unwrap();
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "DropQueuedAsk"), "{:?}", sent.borrow());
        assert_eq!(app.status, "queued ask dropped");
        assert!(!app.ctx().ticket_queued, "the refresh read it gone");
        // Queue one again, then send now over it: the status says the
        // waiting one went.
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        for c in "later".chars() {
            press(&mut app, c);
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.status, "queued ∙ after T-9");
        assert!(app.ctx().ticket_queued, "the refresh read it listed");
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert_eq!(field_text(&app), "", "the fake keeps no text; the field is on the entry");
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(!app.ctx().ask_queued);
        for c in "now please".chars() {
            press(&mut app, c);
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "queued: false"));
        assert_eq!(app.status, "asked ∙ queued ask dropped");
    }

    /// T-565: words queued while the agent is ALREADY on its question are
    /// held at once, and the receipt says the answer comes before the send;
    /// the card's row is the held ask's. A queued receipt that waits on a
    /// question names whose answer.
    #[test]
    fn an_ask_queued_onto_a_question_says_it_is_held() {
        let question =
            SessionState::RequiresAction { reason: mesimon_core::board::Reason::Question };
        let (mut app, sent, _) = app_with_claude(question, false);
        app.rich_keys = true;
        app.client
            .request(Command::SetFollowUpMode { mode: mesimon_core::board::FollowUpMode::Queue })
            .unwrap();
        app.refresh().unwrap();
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_queued);
        for c in "then commit".chars() {
            press(&mut app, c);
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "queued: true"), "{:?}", sent.borrow());
        assert_eq!(app.status, "queued ∙ held ∙ agent asked ∙ answer it, then you send");
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("agent asked ∙ you send"));
        assert!(app.ctx().ticket_held, "its ^y is the person's send");

        let own = "T-1";
        let t3 = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        assert_eq!(
            queued_status("queued", "queued ∙ sends next", &t3(&["T-3"]), &t3(&["T-3"]), own),
            "queued ∙ after T-3's answer"
        );
        assert_eq!(
            queued_status("queued", "queued ∙ sends next", &t3(&[own]), &t3(&[own]), own),
            "queued ∙ after your answer"
        );
        assert_eq!(
            queued_status("claude wakes", "-", &t3(&["T-4", "T-3"]), &t3(&["T-3"]), own),
            "claude wakes ∙ after T-3's answer +1"
        );
        assert_eq!(queued_status("queued", "next", &[], &[], own), "next");
    }

    /// The owed row's words, and the in-flight form.
    #[test]
    fn the_owed_row_names_what_it_waits_on() {
        let (mut app, _sent, _) = app_with_claude(SessionState::Running, false);
        use mesimon_core::command::PendingAction::{Ask, Merge, Rebase};
        let row = |app: &mut App, waits_on: Vec<&str>, in_flight: bool, action| {
            app.pending = vec![mesimon_core::command::Pending {
                ticket: ulid::Ulid(1),
                action,
                waits_on: waits_on.into_iter().map(String::from).collect(),
                asking: Vec::new(),
                text: None,
                in_flight,
                by: None,
                sends: false,
                accept_plan: false,
                plan: false,
                held: None,
                deliver: mesimon_core::command::Deliver::Idle,
            }];
            app.pending_row(ulid::Ulid(1)).unwrap()
        };
        let own = app.board.tickets[0].short_key.clone();
        assert_eq!(row(&mut app, vec![], false, Ask), "queued ∙ sends next");
        assert_eq!(row(&mut app, vec![&own], false, Ask), "queued ∙ after its turn");
        assert_eq!(row(&mut app, vec!["T-3", &own], false, Ask), "queued ∙ after T-3");
        assert_eq!(row(&mut app, vec!["T-3", "T-4", "T-5"], false, Ask), "queued ∙ after T-3 +2");
        assert_eq!(row(&mut app, vec![], true, Ask), "queued ∙ sending");
        // A question is not a turn that ends by itself (T-565): the row
        // says whose ANSWER it waits on, and names that one first.
        let asked = |app: &mut App, waits_on: Vec<&str>, asking: Vec<&str>| {
            app.pending = vec![mesimon_core::command::Pending {
                ticket: ulid::Ulid(1),
                action: Ask,
                waits_on: waits_on.into_iter().map(String::from).collect(),
                asking: asking.into_iter().map(String::from).collect(),
                text: None,
                in_flight: false,
                by: None,
                sends: false,
                accept_plan: false,
                plan: false,
                held: None,
                deliver: mesimon_core::command::Deliver::Idle,
            }];
            app.pending_row(ulid::Ulid(1)).unwrap()
        };
        assert_eq!(asked(&mut app, vec![&own], vec![&own]), "queued ∙ after your answer");
        assert_eq!(asked(&mut app, vec!["T-3", &own], vec!["T-3"]), "queued ∙ after T-3's answer");
        assert_eq!(
            asked(&mut app, vec!["T-5", "T-3", "T-4"], vec!["T-3"]),
            "queued ∙ after T-3's answer +2",
            "the question is named over the turns, which end by themselves"
        );
        assert_eq!(asked(&mut app, vec!["T-3", &own], vec![&own]), "queued ∙ after T-3");
        // The crown's held ask (T-413) names its author and waits on nobody
        // but the person (T-551) — never the checkout it lists.
        app.pending = vec![mesimon_core::command::Pending {
            ticket: ulid::Ulid(1),
            action: Ask,
            waits_on: vec!["T-3".into()],
            asking: Vec::new(),
            text: Some("commit it".into()),
            in_flight: false,
            by: Some("T-411".into()),
            sends: false,
            accept_plan: false,
            plan: false,
            held: None,
            deliver: mesimon_core::command::Deliver::Idle,
        }];
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("T-411 asks ∙ you send"));
        assert!(app.ticket_queued(ulid::Ulid(1)), "^y and ^u apply to it");
        assert!(app.ticket_held(ulid::Ulid(1)));
        // Sent and waiting on its ack, it is the queue's again.
        app.pending[0].in_flight = true;
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("queued ∙ sending"));
        assert!(!app.ticket_held(ulid::Ulid(1)));
        // A four-digit key still fits the card's 22 cells.
        app.pending[0].in_flight = false;
        app.pending[0].by = Some("T-1544".into());
        let words = app.pending_row(ulid::Ulid(1)).unwrap();
        assert_eq!(words.chars().count(), 22, "{words}");
        // A person's own ask is not held: the queue delivers it.
        app.pending[0].by = None;
        assert!(!app.ticket_held(ulid::Ulid(1)));
        // One the board lets the crown send (T-550) is the queue's, and
        // reads as the queue's; `^y` still hurries it and `^u` takes it back.
        app.pending[0].by = Some("T-411".into());
        app.pending[0].sends = true;
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("queued ∙ after T-3"));
        assert!(app.ticket_queued(ulid::Ulid(1)));
        assert!(!app.ticket_held(ulid::Ulid(1)));
        // Parked while its agent was on a question (T-565), the same ask
        // is held: the person answers before anything is sent, and the row
        // says so while the question is up — then that the send is theirs.
        app.pending[0].held = Some("agent asked".into());
        app.pending[0].waits_on = Vec::new();
        app.pending[0].asking = vec![own.clone()];
        assert!(app.ticket_held(ulid::Ulid(1)));
        assert_eq!(
            app.pending_row(ulid::Ulid(1)).as_deref(),
            Some("T-411 asks ∙ you answer first")
        );
        app.pending[0].asking = Vec::new();
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("T-411 asks ∙ you send"));
        // A person's own held ask leads with the stop already.
        app.pending[0].by = None;
        app.pending[0].asking = vec![own.clone()];
        assert_eq!(app.pending_row(ulid::Ulid(1)).as_deref(), Some("agent asked ∙ you send"));
        assert_eq!(row(&mut app, vec![], false, Merge), "auto-merge ∙ next");
        assert_eq!(row(&mut app, vec!["T-3"], false, Merge), "auto-merge ∙ after T-3");
        assert_eq!(row(&mut app, vec![], false, Rebase), "rebase ask ∙ next");
        assert_eq!(row(&mut app, vec!["T-3", "T-4"], false, Rebase), "rebase ask ∙ after T-3 +1");
        // A merge the checkout refused (T-289): the reason travels on `text`
        // and outranks what the row waits on — quiet is not what it needs.
        // The ask's own `text` is its words, and must not read as a refusal.
        let blocked = |app: &mut App, waits_on: Vec<&str>, action| {
            app.pending = vec![mesimon_core::command::Pending {
                ticket: ulid::Ulid(1),
                action,
                waits_on: waits_on.into_iter().map(String::from).collect(),
                asking: Vec::new(),
                text: Some("uncommitted changes in the main checkout".into()),
                in_flight: false,
                by: None,
                sends: false,
                accept_plan: false,
                plan: false,
                held: None,
                deliver: mesimon_core::command::Deliver::Idle,
            }];
            app.pending_row(ulid::Ulid(1)).unwrap()
        };
        assert_eq!(blocked(&mut app, vec![], Merge), "auto-merge ∙ blocked");
        assert_eq!(blocked(&mut app, vec!["T-3", "T-4"], Merge), "auto-merge ∙ blocked");
        assert_eq!(blocked(&mut app, vec!["T-3"], Ask), "queued ∙ after T-3");
        app.pending.clear();
        assert!(app.pending_row(ulid::Ulid(1)).is_none());
        assert!(!app.owed(ulid::Ulid(1)));
    }

    /// `↑` in the prompt field recalls what was asked before, newest first;
    /// `↓` walks back toward the present, and the step past the newest ask
    /// is the draft that was under the cursor when the walk began. A recalled
    /// ask is sent as-is by Enter, and sending it again moves it to the end
    /// of the walk rather than listing it twice.
    #[test]
    fn prompt_field_walks_its_history_and_comes_back_to_the_draft() {
        fn field(app: &App) -> String {
            match &app.mode {
                Mode::Input { buffer, .. } => buffer.as_str().to_string(),
                m => panic!("not in a field: {m:?}"),
            }
        }
        fn open(app: &mut App) {
            app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
            assert!(matches!(app.mode, Mode::Input { purpose: InputPurpose::Prompt { .. }, .. }));
        }
        fn up(app: &mut App) {
            app.handle_key(KeyCode::Up, KeyModifiers::NONE).unwrap();
        }
        fn down(app: &mut App) {
            app.handle_key(KeyCode::Down, KeyModifiers::NONE).unwrap();
        }
        fn ask(app: &mut App, text: &str) {
            open(app);
            for c in text.chars() {
                press(app, c);
            }
            app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        }
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;

        // No past: the arrows are inert and the draft is untouched.
        open(&mut app);
        press(&mut app, 'x');
        up(&mut app);
        down(&mut app);
        assert_eq!(field(&app), "x", "nothing to recall yet");
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();

        ask(&mut app, "run the tests");
        ask(&mut app, "rebase");

        open(&mut app);
        for c in "dra".chars() {
            press(&mut app, c);
        }
        up(&mut app);
        assert_eq!(field(&app), "rebase", "first ↑ is the newest ask");
        up(&mut app);
        assert_eq!(field(&app), "run the tests", "second ↑ is one older");
        up(&mut app);
        assert_eq!(field(&app), "run the tests", "the oldest is a wall, not a wrap");
        down(&mut app);
        assert_eq!(field(&app), "rebase");
        down(&mut app);
        assert_eq!(field(&app), "dra", "↓ past the newest ask is the draft again");
        assert!(
            matches!(
                &app.mode,
                Mode::Input { purpose: InputPurpose::Prompt { walk: None, .. }, .. }
            ),
            "back on the draft, the walk is over"
        );
        down(&mut app);
        assert_eq!(field(&app), "dra", "and stays the draft");

        // Recall the oldest and send it: it travels verbatim and moves to the
        // end of the walk — one copy, newest position.
        up(&mut app);
        up(&mut app);
        assert_eq!(field(&app), "run the tests");
        sent.borrow_mut().clear();
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "run the tests"));
        assert_eq!(app.prompt_history, vec!["rebase".to_string(), "run the tests".to_string()]);
        open(&mut app);
        up(&mut app);
        assert_eq!(field(&app), "run the tests", "the repeat is now the newest");
    }

    /// The finger is still holding shift from the press that opened the
    /// field, so the second Shift+Enter has to land somewhere — and sending
    /// is the only thing it could sanely mean.
    #[test]
    fn a_second_shift_enter_sends_the_prompt_too() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        for c in "ship it".chars() {
            press(&mut app, c);
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(sent_contains(&sent, "ship it"), "{:?}", sent.borrow());
        assert_eq!(app.mode, Mode::Normal);
    }

    /// Esc leaves without asking anything, the way every other field here
    /// does — a prompt is a turn of somebody's conversation and must never
    /// be delivered by a key that means "never mind".
    #[test]
    fn esc_abandons_a_prompt_without_sending_it() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        for c in "oops".chars() {
            press(&mut app, c);
        }
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(!sent_contains(&sent, "PromptSession"), "{:?}", sent.borrow());
    }

    /// T-379. Shift+Enter over an EMPTY claude seat opens the ask field
    /// instead of starting on the title at once: the words are the first
    /// prompt, a blank Enter is the title, and on a shared checkout the
    /// delivery row offers `now` / `queued`. A quiet checkout opens at
    /// `now`. Nothing spawns until Enter, and the board never leaves. A
    /// shell on the ticket is not a claude, so the seat is still empty.
    #[test]
    fn shift_enter_on_a_ticket_without_claude_opens_the_field_and_starts_on_enter() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        app.rich_keys = true;
        assert!(app.ctx().has_ticket);
        assert!(!app.ctx().ticket_has_agent);
        assert!(!app.ctx().checkout_busy);
        assert_eq!(
            keymap::hint_for(Scope::Board, Verb::Prompt, &app.ctx()),
            Some(("shift+enter", "start + ask agent"))
        );
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(
            matches!(
                app.mode,
                Mode::Input { purpose: InputPurpose::Prompt { queued: false, .. }, .. }
            ),
            "the field opens at now: {:?}",
            app.mode
        );
        assert!(app.ctx().ask_queueable, "a shared checkout offers the toggle");
        assert!(!sent_contains(&sent, "SpawnSession"), "nothing spawned yet: {:?}", sent.borrow());
        assert!(!sent_contains(&sent, "PromptSession"), "{:?}", sent.borrow());
        // Typed words are the first prompt, and the daemon starts claude on
        // them through the ask road — never a bare spawn from here.
        for c in "ship it".chars() {
            press(&mut app, c);
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(sent_contains(&sent, "ship it"), "{:?}", sent.borrow());
        assert!(sent_contains(&sent, "queued: false"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "SpawnSession"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "CreateTicket"), "nothing minted: {:?}", sent.borrow());
        assert_eq!(app.status, "agent started ∙ asked");
        assert!(app.board.live_agent(ulid::Ulid(1)).is_some());
        assert_eq!(app.screen, Screen::Board, "the board never leaves");
        assert!(app.pending_attach.is_none(), "no handover");

        // A blank Enter is the title: the composed start, one press late.
        let (mut app, sent, _) = app_with_shell(SessionState::Running);
        app.rich_keys = true;
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(matches!(app.mode, Mode::Input { .. }), "a shell is not an agent: {:?}", app.mode);
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(sent_contains(&sent, "PromptSession"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "SpawnSession"), "{:?}", sent.borrow());
        assert_eq!(app.status, "agent started ∙ asked");

        // Shift+Tab parks the start behind the checkout's current holder,
        // even on a quiet one: the user chose to wait.
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        app.rich_keys = true;
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_queued);
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "queued: true"), "{:?}", sent.borrow());
        assert_eq!(app.status, "agent starts ∙ after T-9");
        assert!(app.ctx().ticket_queued, "the card carries it now");

        // Esc opens nothing and starts nothing.
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        app.rich_keys = true;
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(sent.borrow().iter().all(|r| !r.contains("Session")), "{:?}", sent.borrow());
    }

    /// T-294. The same press, with another claude working in the same
    /// checkout: the field opens at `queued` instead of spawning, and a
    /// blank Enter is the press it interrupted — start claude on the title,
    /// when the checkout is free.
    #[test]
    fn shift_enter_on_an_empty_seat_asks_now_or_queued_while_the_checkout_works() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        press(&mut app, 'j');
        assert!(!app.ctx().ticket_has_agent, "the cursor is on the seatless ticket");
        assert!(app.ctx().checkout_busy, "an agent is mid-turn in the same checkout");
        assert_eq!(
            keymap::hint_for(Scope::Board, Verb::Prompt, &app.ctx()),
            Some(("shift+enter", "start + ask agent"))
        );
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(
            matches!(
                app.mode,
                Mode::Input { purpose: InputPurpose::Prompt { queued: true, .. }, .. }
            ),
            "the field opens at queued: {:?}",
            app.mode
        );
        assert!(app.ctx().ask_queueable, "the row shows on an empty seat too");
        assert!(!sent_contains(&sent, "SpawnSession"), "nothing spawned yet: {:?}", sent.borrow());
        // A blank Enter is the whole gesture: the title is the prompt.
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "queued: true"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "SpawnSession"), "{:?}", sent.borrow());
        assert_eq!(app.status, "agent starts ∙ after T-9");
        assert!(app.ctx().ticket_queued, "the card carries it now");
        assert_eq!(app.pending_row(ulid::Ulid(2)).as_deref(), Some("starts ∙ after T-9"));

        // Shift+Tab is how the start jumps the queue.
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(!app.ctx().ask_queued);
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.status, "agent started ∙ asked");
        assert!(app.board.live_agent(ulid::Ulid(2)).is_some());
    }

    /// T-294. A parked claude is the other seat a press would start a turn
    /// in, so it queues on a busy checkout and wakes at once on a quiet one.
    #[test]
    fn shift_enter_on_a_sleeping_claude_queues_the_wake_while_the_checkout_works() {
        let (mut app, sent, _) = app_with_claude(SessionState::Sleeping, false);
        app.rich_keys = true;
        assert!(!app.ctx().checkout_busy, "a parked agent works on nothing");
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(
            matches!(
                app.mode,
                Mode::Input { purpose: InputPurpose::Prompt { queued: false, .. }, .. }
            ),
            "a quiet checkout wakes it now"
        );
        assert!(app.ctx().ask_queueable, "and the toggle is offered either way");
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();

        // Somebody else takes the checkout.
        app.board_mut().sessions.push(mesimon_core::board::SessionRecord::new(
            uuid::Uuid::from_u128(8),
            SessionKind::Claude,
            ulid::Ulid(2),
            vec!["claude".into()],
            "/repo".into(),
            SessionState::Running,
        ));
        assert!(app.ctx().checkout_busy);
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(matches!(
            app.mode,
            Mode::Input { purpose: InputPurpose::Prompt { queued: true, .. }, .. }
        ));
        for c in "carry on".chars() {
            press(&mut app, c);
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "queued: true"), "{:?}", sent.borrow());
        assert_eq!(app.status, "agent wakes ∙ after T-9");
    }

    /// T-603. A plain start awake at its composer, `idle` with no stop
    /// reason, never took a prompt: the field says a blank Enter sends the
    /// brief, and it does, where it used to close without a word. On a seat
    /// that has conversed a blank Enter still sends nothing, and says so.
    #[test]
    fn a_blank_ask_at_a_seat_that_never_took_a_prompt_sends_the_brief() {
        let idle = SessionState::Idle { stop_reason: mesimon_core::board::StopReason::Unknown };
        let (mut app, sent, _) = app_with_claude(idle.clone(), false);
        app.rich_keys = true;
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(!sent_contains(&sent, "PromptSession"), "{:?}", sent.borrow());
        assert_eq!(app.status, "nothing to send", "a blank Enter is never silent");

        let mut b = board_three_columns();
        let mut rec = mesimon_core::board::SessionRecord::new(
            uuid::Uuid::from_u128(7),
            SessionKind::Claude,
            ulid::Ulid(1),
            vec!["claude".into()],
            "/repo".into(),
            idle,
        );
        rec.unprompted = true;
        b.sessions.push(rec);
        let (mut app, sent) = App::for_test_logged(b, theme(), false);
        app.rich_keys = true;
        assert!(app.ticket_unprompted(ulid::Ulid(1)));
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(
            matches!(app.mode, Mode::Input { purpose: InputPurpose::Prompt { .. }, .. }),
            "the field opens: {:?}",
            app.mode
        );
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "PromptSession"), "{:?}", sent.borrow());
        assert!(sent_contains(&sent, r#"text: """#), "blank, for the daemon: {:?}", sent.borrow());
        assert_eq!(app.status, "brief sent");
    }

    /// T-390: live-pane follow-ups use the per-board Queue/Steer default.
    #[test]
    fn a_paned_ask_obeys_the_board_follow_up_default() {
        let (mut app, _sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        assert!(app.ctx().checkout_busy, "its own agent holds the checkout");
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(app.ctx().ask_queued, "Queue is the default");
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        app.client
            .request(Command::SetFollowUpMode { mode: mesimon_core::board::FollowUpMode::Steer })
            .unwrap();
        app.refresh().unwrap();
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(!app.ctx().ask_queued, "Steer is an explicit board preference");
    }

    /// T-294 / T-379. A worktree ticket's checkout is its own: nothing to
    /// wait for, so the field opens at `now` with no toggle row, and
    /// Shift+Tab does nothing there.
    #[test]
    fn a_worktree_ticket_never_stops_to_ask() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = true;
        app.board_mut().tickets[1].workspace =
            Some(mesimon_core::board::WorkspaceStrategy::Worktree);
        press(&mut app, 'j');
        assert!(!app.ctx().checkout_busy, "another checkout entirely");
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(
            matches!(
                app.mode,
                Mode::Input { purpose: InputPurpose::Prompt { queued: false, .. }, .. }
            ),
            "the field opens at now: {:?}",
            app.mode
        );
        assert!(!app.ctx().ask_queueable, "a worktree ticket has no toggle");
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        assert!(!app.ctx().ask_queued, "the key did nothing");
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "queued: false"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "SpawnSession"), "{:?}", sent.borrow());
        assert_eq!(app.status, "agent started ∙ asked");
    }

    /// A parked agent has no box to type into, and `Sleeping` is LIVE — so
    /// the field opens as on a paned claude, the hint says the wake it adds,
    /// and the send is the same `PromptSession`: the daemon wakes the agent
    /// and parks the words for its pane (2026-09-04). Never a second spawn
    /// beside it, and never a handover — the board is where the ask lands.
    #[test]
    fn shift_enter_on_a_sleeping_claude_wakes_it_and_asks() {
        let (mut app, sent, _) = app_with_claude(SessionState::Sleeping, false);
        app.rich_keys = true;
        assert!(app.ctx().ticket_has_agent, "the session is live — parked, but live");
        assert!(!app.ctx().ticket_promptable, "…and has no pane to type into");
        assert_eq!(
            keymap::hint_for(Scope::Board, Verb::Prompt, &app.ctx()),
            Some(("shift+enter", "wake + ask agent"))
        );
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(
            matches!(app.mode, Mode::Input { purpose: InputPurpose::Prompt { .. }, .. }),
            "the field opens on the card"
        );
        for c in "carry on".chars() {
            press(&mut app, c);
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(sent_contains(&sent, "PromptSession"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "SpawnSession"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "ResumeSession"), "the wake is the daemon's");
        assert_eq!(app.status, "woke agent ∙ asked");
        assert_eq!(app.screen, Screen::Board);
        assert!(app.pending_attach.is_none(), "no handover");
    }

    /// `c` copies the ticket (T-674): its id, then its title, then the two
    /// together, round again; the status line says what landed and what the
    /// next press copies. It starts, wakes and attaches nothing.
    #[test]
    fn c_cycles_id_title_and_both_and_starts_nothing() {
        let copied = || crate::clipboard::COPIED.with(|c| c.borrow().last().cloned());
        let (mut app, sent, _) = app_with_claude(SessionState::Sleeping, false);
        let want = [
            ("copy id", "T-1", "T-1 id copied ∙ c again copies the title"),
            ("copy title", "ticket 1", "T-1 title copied ∙ c again copies the id + title"),
            ("copy id + title", "T-1 ticket 1", "T-1 id + title copied ∙ c again copies the id"),
            ("copy id", "T-1", "T-1 id copied ∙ c again copies the title"),
        ];
        for (hint, text, status) in want {
            assert_eq!(
                keymap::hint_for(Scope::Board, Verb::CopyTicket, &app.ctx()),
                Some(("c", hint))
            );
            press(&mut app, 'c');
            assert_eq!(copied().as_deref(), Some(text));
            assert_eq!(app.status, status);
        }
        assert!(!sent_contains(&sent, "ResumeSession"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "SpawnSession"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "FocusStart"), "{:?}", sent.borrow());

        // Any other verb starts the cycle over, and so does another ticket.
        press(&mut app, 'c');
        press(&mut app, 'j');
        press(&mut app, 'k');
        press(&mut app, 'c');
        assert_eq!(copied().as_deref(), Some("T-1"));
        press(&mut app, 'j');
        press(&mut app, 'c');
        assert_eq!(copied().as_deref(), Some("T-2"));

        // The ticket page's `c` is the same cycle on the page's ticket.
        app.screen = Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 };
        press(&mut app, 'c');
        assert_eq!(copied().as_deref(), Some("T-1"));
        press(&mut app, 'c');
        assert_eq!(copied().as_deref(), Some("ticket 1"));
        assert!(matches!(app.screen, Screen::Ticket { .. }), "no handover");
    }

    /// The legacy floor. A terminal that cannot spell Shift+Enter sends a
    /// plain Enter, which on the board means "go to the agent" — so the key
    /// must resolve to nothing here rather than half-working.
    #[test]
    fn without_rich_keys_the_prompt_key_is_the_plain_enter_it_arrives_as() {
        let (mut app, _sent, _) = app_with_claude(SessionState::Running, false);
        app.rich_keys = false;
        assert!(app.ctx().ticket_promptable);
        assert_eq!(
            mesimon_core::keymap::resolve(
                mesimon_core::keymap::Scope::Board,
                mesimon_core::keymap::Key::ShiftEnter,
                &app.ctx()
            ),
            None
        );
    }

    /// Shift+Enter is the whole gesture in one press: the ticket exists, an
    /// agent is on it, the title has been ASKED (not just typed), and the
    /// board never went away.
    #[test]
    fn shift_enter_composes_and_starts_without_leaving_the_board() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        app.rich_keys = true;
        press(&mut app, 'o');
        press(&mut app, 'n');
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(sent_contains(&sent, "CreateTicketWithNote"));
        assert!(
            sent_contains(&sent, "submit_prompt: true"),
            "the title is submitted, not merely prefilled: {:?}",
            sent.borrow()
        );
        assert_eq!(app.screen, Screen::Board, "the board never leaves");
        assert!(app.pending_attach.is_none(), "no handover — that is the point");
        assert_eq!(app.mode, Mode::Normal, "the composer closed");
        // The agent is already running, so the fresh-ticket Enter window must
        // NOT be armed — the next Enter means what it always means.
        assert_eq!(app.just_created, None);
    }

    /// Same gesture on a terminal that cannot spell the key: crossterm reports
    /// a plain Enter, and a plain Enter is exactly what the user gets — the
    /// ticket, the armed fast path, no surprise agent.
    #[test]
    fn shift_enter_degrades_to_plain_save_without_rich_keys() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        assert!(!app.rich_keys);
        press(&mut app, 'o');
        press(&mut app, 'n');
        // The atom still arrives (this test presses it); the keymap refuses it.
        app.handle_key(KeyCode::Enter, KeyModifiers::SHIFT).unwrap();
        assert!(!sent_contains(&sent, "CreateTicket"), "the key is inert, not half-bound");
        assert!(matches!(app.mode, Mode::Input { .. }), "still composing");
    }

    /// Tags picked with `^t` while composing ride the mint itself (T-243):
    /// one `CreateTicketWithNote` carries them and nothing is replayed as
    /// `SetTag` once the ticket has an id — the daemon wears them as it
    /// mints, so the card lands with its pips.
    #[test]
    fn composer_tags_ride_the_mint() {
        let mut board = board_three_columns();
        board.register_tag(1, "BUG").expect("registered");
        let (mut app, sent) = App::for_test_logged(board, theme(), false);
        press(&mut app, 'o');
        press(&mut app, 'n');
        ctrl(&mut app, 't');
        assert_eq!(app.tag_cell().map(|(g, n, _)| (g, n)), Some((1, "BUG".to_string())));
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert!(!sent_contains(&sent, "SetTag"), "no ticket to tag yet: {:?}", sent.borrow());
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        let mint = sent
            .borrow()
            .iter()
            .find(|s| s.starts_with("CreateTicketWithNote"))
            .cloned()
            .expect("minted");
        assert!(mint.contains("\"BUG\""), "the pick rides the mint: {mint}");
        assert!(!sent_contains(&sent, "SetTag"), "nothing replayed: {:?}", sent.borrow());
        let card = app.board.tickets.iter().find(|t| t.short_key == "T-999").expect("landed");
        assert_eq!(card.tags.len(), 1, "wearing it on arrival: {:?}", card.tags);
        assert_eq!(card.tags[0].name, "BUG");
    }

    /// A refused mint — a full group, a note past its limit, a barred store —
    /// leaves no half-made ticket and hands the draft back (T-243): the
    /// composer reopens holding the title and the description, the daemon's
    /// reason on the status line.
    #[test]
    fn a_refused_mint_keeps_the_draft() {
        let sent = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let fake = super::test_support::FakeTransport {
            board: board_three_columns(),
            grace: vec![],
            external: vec![],
            resources: Resources::default(),
            shell_env: Default::default(),
            git: Default::default(),
            pending: Vec::new(),
            automation: Default::default(),
            status_top: false,
            claude_md: Default::default(),
            sent: sent.clone(),
            refuse_focus: false,
            refuse_mint: true,
            notes: std::collections::HashMap::new(),
            terminals: Vec::new(),
            machine_tiers: Default::default(),
            usage: Default::default(),
            clean_checkout: false,
        };
        let mut app = App::new(Box::new(fake), PathBuf::from("/repo/kanban-tui"), theme())
            .expect("fake transport snapshot");
        press(&mut app, 'o');
        press(&mut app, 'n');
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        for c in "why".chars() {
            press(&mut app, c);
        }
        ctrl(&mut app, 's');
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "CreateTicketWithNote"), "{:?}", sent.borrow());
        match &app.mode {
            Mode::Input { purpose: InputPurpose::Create { description, .. }, buffer } => {
                assert_eq!(buffer.as_str(), "n", "the title is back");
                assert_eq!(description.as_deref(), Some("why"), "and the description");
            }
            other => panic!("the draft is gone: {other:?}"),
        }
        assert_eq!(app.status, "could not create ticket");
        assert_eq!(app.just_created, None);
        assert!(app.board.tickets.iter().all(|t| t.title != "n"), "no half-made ticket");
        assert!(!sent_contains(&sent, "WriteNote"), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "SetTag"), "{:?}", sent.borrow());
    }

    fn ctrl(app: &mut App, c: char) {
        app.handle_key(KeyCode::Char(c), KeyModifiers::CONTROL).unwrap();
    }

    /// The picker opens on the first cell, and on a board with no tags that
    /// cell is `+ new` — so the very first thing Enter does is make one.
    /// Nothing is seeded, and there is no setup step before that works.
    #[test]
    fn the_picker_starts_on_new_when_nothing_is_registered() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        ctrl(&mut app, 't');
        assert_eq!(app.scope(), Scope::TagChord);
        assert!(app.tag_cell().is_none(), "the only cell is `+ new`");

        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(
            app.tag_armed.as_ref().expect("armed").naming.is_some(),
            "enter on `+ new` opens the name field"
        );
        // Digits and hjkl are TEXT while naming, not picker keys.
        for c in "b1u2g".chars() {
            press(&mut app, c);
        }
        assert_eq!(
            app.tag_armed
                .as_ref()
                .and_then(|a| a.naming.as_ref())
                .map(|(_, b)| b.as_str().to_string()),
            Some("b1u2g".to_string()),
            "the field owns every printable key"
        );
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "RegisterTag"), "the name is registered");
        assert!(sent_contains(&sent, "b1u2g"));
    }

    /// The name field is `edit_buffer_key`'s, like every other one-line
    /// field: a Ctrl+letter is an editing key or nothing, never the letter.
    /// The picker's own copy of that match had no `!CONTROL` guard, so
    /// `ctrl+x` typed an `x` into the tag's name (T-684).
    #[test]
    fn ctrl_letter_in_the_tag_name_field_inserts_nothing() {
        let (mut app, _sent) = App::for_test_logged(board_three_columns(), theme(), false);
        ctrl(&mut app, 't');
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        let name = |app: &App| {
            app.tag_armed
                .as_ref()
                .and_then(|a| a.naming.as_ref())
                .map(|(_, b)| b.as_str().to_string())
        };
        assert_eq!(name(&app), Some(String::new()), "the field is open and empty");
        for c in "xbcp".chars() {
            ctrl(&mut app, c);
        }
        assert_eq!(name(&app), Some(String::new()), "ctrl+letter types nothing");
        press(&mut app, 'a');
        ctrl(&mut app, 'u');
        assert_eq!(name(&app), Some(String::new()), "ctrl+u still kills to the start");
    }

    /// Enter on a tag wears it; Enter again takes it off. Creating and
    /// wearing are separate gestures, so registering never tags anything.
    #[test]
    fn enter_toggles_the_tag_under_the_cursor() {
        let mut board = board_three_columns();
        board.register_tag(1, "BUG").expect("registered");
        let id = board.tickets[0].id;
        let (mut app, sent) = App::for_test_logged(board, theme(), false);
        app.cursor_col = 0;
        app.cursor_row = Some(0);
        assert_eq!(app.subject(), Some(id));

        ctrl(&mut app, 't');
        assert_eq!(app.tag_cell().map(|(g, n, _)| (g, n)), Some((1, "BUG".to_string())));
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "SetTag"));
        assert!(sent_contains(&sent, "Some(\"BUG\")"), "{:?}", sent.borrow());

        // Wearing it, Enter clears the axis.
        app.board_mut().ticket_mut(id).expect("ticket").set_tag(1, Some("BUG".into()));
        sent.borrow_mut().clear();
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent.borrow().join(" ").contains("name: None"), "{:?}", sent.borrow());
    }

    /// The terminal's late answer to the colour query, fed the way `tick`
    /// feeds it: `alt+]` `1` `1` `;` `rgb:…` `alt+\`. The `1`s are the
    /// quick-tag key and the `r` is rename, and neither may fire — and the
    /// machine is idle again afterwards, so the next real `r` does.
    #[test]
    fn a_late_colour_reply_neither_tags_nor_renames() {
        let mut board = board_three_columns();
        board.register_tag(1, "BUG").expect("registered");
        let (mut app, sent) = App::for_test_logged(board, theme(), false);
        app.cursor_col = 0;
        app.cursor_row = Some(0);
        app.on_key(KeyCode::Char(']'), KeyModifiers::ALT).unwrap();
        for c in "11;rgb:1e1e/1e1e/1e1e".chars() {
            app.on_key(KeyCode::Char(c), KeyModifiers::NONE).unwrap();
        }
        app.on_key(KeyCode::Char('\\'), KeyModifiers::ALT).unwrap();
        assert!(!sent_contains(&sent, "SetTag"), "{:?}", sent.borrow());
        assert!(!matches!(app.mode, Mode::Input { .. }), "rename opened");
        assert!(app.tag_flash.is_none());

        assert!(app.on_key(KeyCode::Char('r'), KeyModifiers::NONE).unwrap());
        assert!(matches!(app.mode, Mode::Input { .. }), "a real r still renames");
    }

    /// The same reply landing INSIDE a text field — the composer is open —
    /// types nothing into it, since the swallow sits ahead of the barrier
    /// that strips Alt.
    #[test]
    fn a_late_colour_reply_types_nothing_into_an_open_field() {
        let mut app = app_three_columns();
        press(&mut app, 'o');
        press(&mut app, 'x');
        app.on_key(KeyCode::Char(']'), KeyModifiers::ALT).unwrap();
        for c in "11;rgb:1e1e/1e1e/1e1e".chars() {
            app.on_key(KeyCode::Char(c), KeyModifiers::NONE).unwrap();
        }
        app.on_key(KeyCode::Char('\\'), KeyModifiers::ALT).unwrap();
        let Mode::Input { buffer, .. } = &app.mode else { panic!("composer closed") };
        assert_eq!(buffer.as_str(), "x");
    }

    /// hjkl walks the grid and a digit jumps to that group's row, stepping
    /// along it when pressed again — one finger reaches every tag on an axis.
    #[test]
    fn the_cursor_walks_and_digits_jump() {
        let mut board = board_three_columns();
        for n in ["BUG", "REGR", "FTR"] {
            board.register_tag(1, n).expect("registered");
        }
        board.register_tag(2, "DEV").expect("registered");
        let (mut app, _sent) = App::for_test_logged(board, theme(), false);
        ctrl(&mut app, 't');

        let name = |a: &App| a.tag_cell().map(|(_, n, _)| n);
        assert_eq!(name(&app).as_deref(), Some("BUG"));
        press(&mut app, 'l');
        assert_eq!(name(&app).as_deref(), Some("REGR"));
        press(&mut app, 'h');
        assert_eq!(name(&app).as_deref(), Some("BUG"));
        // Down into a shorter row: the column trims to what that row
        // actually reaches instead of pointing past its end.
        press(&mut app, 'l');
        press(&mut app, 'l');
        assert_eq!(app.tag_armed.as_ref().expect("armed").col, 2);
        press(&mut app, 'j');
        let arm = app.tag_armed.as_ref().expect("armed");
        assert_eq!(arm.row, 1);
        assert_eq!(arm.col, 1, "clamped to the last cell of the shorter row (`+ new`)");
        press(&mut app, 'h');
        assert_eq!(name(&app).as_deref(), Some("DEV"));

        // A digit jumps; the same digit again steps along, and the row
        // wraps rather than going dead on its last cell.
        press(&mut app, '1');
        assert_eq!(name(&app).as_deref(), Some("BUG"));
        press(&mut app, '1');
        assert_eq!(name(&app).as_deref(), Some("REGR"));
        press(&mut app, '1');
        assert_eq!(name(&app).as_deref(), Some("FTR"));
        press(&mut app, '1');
        assert_eq!(name(&app), None, "the `+ new` cell is the row's last stop");
        press(&mut app, '1');
        assert_eq!(name(&app).as_deref(), Some("BUG"), "and then round again");
        press(&mut app, '2');
        assert_eq!(name(&app).as_deref(), Some("DEV"));
        // The empty spare row holds one cell and cycles onto itself.
        press(&mut app, '3');
        press(&mut app, '3');
        let arm = app.tag_armed.as_ref().expect("armed");
        assert_eq!((arm.row, arm.col), (2, 0));
    }

    /// `P` is `p` widened (T-237): it opens every card, and it implies the
    /// cursor card's own peek, so `p` going off takes it along and `P`
    /// going off narrows back to the cursor card rather than to nothing.
    #[test]
    fn shift_p_widens_the_peek_to_every_card() {
        let (mut app, _sent) = App::for_test_logged(board_three_columns(), theme(), false);
        assert!(!app.peek && !app.peek_all);
        press(&mut app, 'P');
        assert!(app.peek && app.peek_all, "every card, the cursor card included");
        assert!(
            app.status.starts_with("showing the latest reply under every card"),
            "{}",
            app.status
        );
        press(&mut app, 'P');
        assert!(app.peek && !app.peek_all, "narrowed to the cursor card, not hidden");
        press(&mut app, 'P');
        press(&mut app, 'p');
        assert!(!app.peek && !app.peek_all, "`p` off hides the lot");
        assert!(app.status.starts_with("replies hidden"), "{}", app.status);
        // Overlay-only, on the board alone: `?` names it, the footer never
        // does (user: "no need to hint this").
        assert!(!app.ctx().peek_on);
        assert_eq!(
            keymap::hint_for(Scope::Board, Verb::PeekAll, &app.ctx()),
            Some(("P", "show every reply"))
        );
        assert!(!keymap::footer_items(Scope::Board, &app.ctx())
            .iter()
            .any(|b| b.verb == Verb::PeekAll));
    }

    /// The rung `p`/`P` leave is a preference (T-365): a press writes it to
    /// the machine's copy — the file, where there is one — and a board that
    /// opens on a remembered rung shows it before any key, because the
    /// resolve is where the two flags come from.
    #[test]
    fn the_reply_row_is_remembered_between_boards() {
        let (mut app, _sent) = App::for_test_logged(board_three_columns(), theme(), false);
        assert_eq!(app.machine_prefs.peek, PeekLevel::Off);
        press(&mut app, 'P');
        assert_eq!(app.machine_prefs.peek, PeekLevel::All);
        assert_eq!(app.machine_prefs.word(PrefKey::Peek), "all");
        press(&mut app, 'P');
        assert_eq!(app.machine_prefs.peek, PeekLevel::Cursor);
        press(&mut app, 'p');
        assert_eq!(app.machine_prefs.peek, PeekLevel::Off);
        // No file under a test app, and the status says so — the road every
        // preference takes, with its words.
        assert_eq!(app.status, "replies hidden for this session");

        // The next board: `run` loads the file and resolves, which is what
        // the seed does here.
        let (mut app, _sent) = App::for_test_logged(board_three_columns(), theme(), false);
        app.seed_pref(|p| p.set_peek(PeekLevel::All));
        assert!(app.peek && app.peek_all, "opened the way it was left");
        assert!(app.ctx().peek_on && app.ctx().peek_all);
        app.seed_pref(|p| p.set_peek(PeekLevel::Cursor));
        assert!(app.peek && !app.peek_all);
        // A board's file cannot set it: the rung is the machine's.
        app.board_prefs.clear(PrefKey::Peek);
        assert!(!app.board_prefs.is_set(PrefKey::Peek));
        assert!(!PrefKey::Peek.board_overridable());
    }

    /// A quick-tag digit opens the card it tagged, and then lets go. The
    /// stripe is one cell and carries no words, so the press that changes it
    /// opens the row that names it — for a moment, and only on that card.
    #[test]
    fn a_quick_tag_flashes_its_card_open() {
        let mut board = board_three_columns();
        board.register_tag(1, "BUG").expect("registered");
        let (mut app, sent) = App::for_test_logged(board, theme(), false);
        app.cursor_col = 0;
        app.cursor_row = Some(0);
        let id = app.subject().expect("a ticket under the cursor");
        assert!(!app.peek_showing(id), "nothing is open before the press");

        press(&mut app, '1');
        assert!(sent_contains(&sent, "SetTag"), "the digit tagged it");
        assert!(app.peek_showing(id), "and opened the card it tagged");
        assert!(!app.peek_showing(ulid::Ulid(2)), "the reveal is one card's, never the board's");

        // A moment, not a mode: the reveal expires on its own clock, and the
        // `p` preference — which is what the footer describes — is untouched.
        app.tag_flash = Some((id, Instant::now() - TAG_FLASH));
        assert!(!app.peek_showing(id));
        assert!(!app.peek, "the flash never sets the preference");
        assert!(!app.ctx().peek_on, "so `p` still offers to show replies");

        // An axis with no vocabulary changed nothing, so it reveals nothing.
        press(&mut app, '4');
        assert!(!app.peek_showing(id));
        assert_eq!(app.status, "no tags in group 4 ∙ ^t makes one");
    }

    /// The board's nudge, in the picker's grid. Along the row it is order —
    /// which is what the row draws and what a repeated digit walks. Across
    /// rows it is the axis itself, the one repair a tag created on the wrong
    /// one has ever had (`d` is the other way off an axis, and it takes the
    /// tag off every ticket on the way).
    #[test]
    fn a_tag_is_carried_along_its_axis_and_onto_another() {
        let mut board = board_three_columns();
        for n in ["A", "B", "C"] {
            board.register_tag(1, n).expect("registered");
        }
        board.register_tag(2, "DEV").expect("registered");
        let (mut app, sent) = App::for_test_logged(board, theme(), false);
        ctrl(&mut app, 't');
        assert_eq!(app.tag_cell().map(|(_, n, _)| n).as_deref(), Some("A"));
        let moves = |sent: &std::cell::RefCell<Vec<String>>| -> Vec<String> {
            sent.borrow().iter().filter(|c| c.contains("MoveTag")).cloned().collect()
        };

        // The left edge of the row: nowhere to go, and nothing said about it.
        sent.borrow_mut().clear();
        press(&mut app, 'H');
        alt(&mut app, KeyCode::Left);
        assert!(moves(&sent).is_empty(), "{:?}", sent.borrow());
        assert!(app.tag_armed.is_some(), "a nudge with nowhere to go is inert, not a dismissal");

        // Along the axis, both spellings, one command.
        press(&mut app, 'L');
        alt(&mut app, KeyCode::Char('l'));
        let log = moves(&sent);
        assert_eq!(log.len(), 2, "{log:?}");
        for line in &log {
            assert!(line.contains("to_group: 1") && line.contains("to_index: 1"), "{line}");
        }

        // Down onto the next axis: the tag JOINS that row, at its end.
        sent.borrow_mut().clear();
        press(&mut app, 'J');
        let log = moves(&sent).join(" ");
        assert!(log.contains("to_group: 2") && log.contains("to_index: 1"), "{log}");
        // And up from the top row is the same nowhere as the left edge.
        sent.borrow_mut().clear();
        press(&mut app, 'K');
        assert!(moves(&sent).is_empty(), "{:?}", sent.borrow());
    }

    /// The accelerator is inert where the move is unavailable, on BOTH kinds
    /// of terminal: the one that sends the Alt atom, and the one that eats
    /// the modifier and composes a character instead. Neither may dismiss the
    /// panel, or `alt+h` would cost the user their place on one machine and
    /// nothing on the next.
    #[test]
    fn an_eaten_option_key_leaves_the_picker_standing() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        ctrl(&mut app, 't');
        assert!(app.tag_cell().is_none(), "the only cell is `+ new` — nothing to carry");
        for code in [KeyCode::Char('h'), KeyCode::Char('j'), KeyCode::Left] {
            alt(&mut app, code);
            assert!(app.tag_armed.is_some(), "{code:?} closed the picker");
        }
        // What macOS Terminal sends for `⌥h` instead of a modifier at all.
        press(&mut app, '\u{2d9}');
        assert!(app.tag_armed.is_some(), "a composed character is not a stray key");
        assert!(!sent_contains(&sent, "MoveTag"), "{:?}", sent.borrow());
    }

    /// A name field types its letters, shifted ones included — the whole
    /// table stands down while `tag_naming`, and Alt goes back to meaning
    /// "by word" there.
    #[test]
    fn a_shifted_letter_is_text_inside_a_name_field() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        ctrl(&mut app, 't');
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        for c in "HJKL".chars() {
            press(&mut app, c);
        }
        assert_eq!(
            app.tag_armed
                .as_ref()
                .and_then(|a| a.naming.as_ref())
                .map(|(_, b)| b.as_str().to_string()),
            Some("HJKL".to_string()),
        );
        assert!(!sent_contains(&sent, "MoveTag"), "{:?}", sent.borrow());
    }

    /// Tab cycles the tint, and it is a registry property — so it repaints
    /// every card wearing that tag, not just this one.
    #[test]
    fn tab_cycles_the_colour() {
        let mut board = board_three_columns();
        board.register_tag(1, "BUG").expect("registered");
        let was = board.tag_def(1, "BUG").expect("registered").tint();
        let (mut app, sent) = App::for_test_logged(board, theme(), false);
        ctrl(&mut app, 't');
        app.handle_key(KeyCode::Tab, KeyModifiers::NONE).unwrap();
        let log = sent.borrow().join(" ");
        assert!(log.contains("SetTagColor"), "{log}");
        let next = (was + 1) % mesimon_core::board::TAG_TINTS;
        assert!(log.contains(&format!("color: {next}")), "{log}");
    }

    /// And Shift+Tab walks the ramp back: from the tint Tab just left, one
    /// press returns, and from the first tint it wraps to the last.
    #[test]
    fn shift_tab_cycles_the_colour_back() {
        let n = mesimon_core::board::TAG_TINTS;
        let mut board = board_three_columns();
        board.register_tag(1, "BUG").expect("registered");
        board.set_tag_color(1, "BUG", 0).expect("tinted");
        let (mut app, sent) = App::for_test_logged(board, theme(), false);
        ctrl(&mut app, 't');
        app.handle_key(KeyCode::BackTab, KeyModifiers::SHIFT).unwrap();
        let log = sent.borrow().join(" ");
        assert!(log.contains("SetTagColor"), "{log}");
        assert!(log.contains(&format!("color: {}", n - 1)), "{log}");
    }

    /// `r` opens the field pre-filled, so a rename is an edit and not a
    /// retype.
    #[test]
    fn rename_starts_from_the_current_name() {
        let mut board = board_three_columns();
        board.register_tag(1, "BUG").expect("registered");
        let (mut app, sent) = App::for_test_logged(board, theme(), false);
        ctrl(&mut app, 't');
        press(&mut app, 'r');
        assert_eq!(
            app.tag_armed
                .as_ref()
                .and_then(|a| a.naming.as_ref())
                .map(|(_, b)| b.as_str().to_string()),
            Some("BUG".to_string())
        );
        for c in "S".chars() {
            press(&mut app, c);
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "RenameTag"));
        assert!(sent_contains(&sent, "BUGS"));
    }

    /// Esc backs out of the field first and closes the picker second: losing
    /// a half-typed name AND the panel to one key is a gesture nobody means.
    #[test]
    fn esc_leaves_the_field_before_the_picker() {
        let (mut app, _sent) = App::for_test_logged(board_three_columns(), theme(), false);
        ctrl(&mut app, 't');
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(app.tag_armed.as_ref().expect("armed").naming.is_some());
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert!(app.tag_armed.is_some(), "still in the picker");
        assert!(app.tag_armed.as_ref().expect("armed").naming.is_none(), "out of the field");
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert!(app.tag_armed.is_none(), "picker closed");
    }

    /// A rename has nothing to start, so the key stays out of its way.
