    #[test]
    fn refused_focus_falls_open_to_the_ticket_screen() {
        let (mut app, _sent, _sid) = app_with_claude(SessionState::Running, true);
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(app.pending_attach.is_none());
        assert_eq!(app.screen, Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 });
        assert!(!app.status.is_empty(), "the refusal shows itself");
    }

    #[test]
    fn unfocus_returns_to_the_focus_origin() {
        // Board-born focus lands back on the board…
        let (mut app, _sent, sid) = app_with_claude(SessionState::Running, false);
        app.screen = Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 };
        app.focused_session_hint = Some(FocusTarget::Session(sid, FocusOrigin::Board));
        app.after_handover().unwrap();
        assert_eq!(app.screen, Screen::Board);
        assert_eq!(app.selected_ticket().map(|t| t.id), Some(ulid::Ulid(1)));
        // …ticket-born focus lands back on the ticket screen.
        let (mut app, _sent, sid) = app_with_claude(SessionState::Running, false);
        app.focused_session_hint = Some(FocusTarget::Session(sid, FocusOrigin::Ticket));
        app.after_handover().unwrap();
        assert_eq!(app.screen, Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 });
    }

    /// `!` opens the SCREEN's directory (T-273): the board's is the checkout,
    /// a ticket page's its attached worktree, else the checkout again — and
    /// the return gives the token back and stays where the key was pressed,
    /// since the terminal is nobody's session and has no origin to land on.
    #[test]
    fn the_terminal_opens_the_screens_directory_and_returns_to_it() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        press(&mut app, '!');
        assert!(sent_contains(&sent, "OpenTerminal { ticket: None }"), "{:?}", sent.borrow());
        assert_eq!(app.pending_attach, Some(vec!["tmux".to_string()]));
        assert_eq!(app.focused_session_hint, Some(FocusTarget::Terminal));
        app.pending_attach = None;
        app.after_handover().unwrap();
        assert!(sent_contains(&sent, "TerminalEnd"), "{:?}", sent.borrow());
        assert_eq!(app.screen, Screen::Board);
        assert!(app.focused_session_hint.is_none());

        // A ticket page whose worktree is attached names its ticket, and the
        // return lands back on the page.
        let t = ulid::Ulid(1);
        app.worktrees.push(WorktreeItem {
            ticket: t,
            branch: "msmn/T-1-x".into(),
            status: "attached".into(),
            merged: false,
            conflict: false,
            ahead: 0,
            needs_rebase: false,
            detail: None,
            path: Some("/wt/T-1-x".into()),
            merged_in: String::new(),
            merged_oid: String::new(),
            repos: vec![],
        });
        app.screen = Screen::Ticket { ticket: t, rail_idx: 0 };
        sent.borrow_mut().clear();
        press(&mut app, '!');
        assert!(sent_contains(&sent, "OpenTerminal { ticket: Some("), "{:?}", sent.borrow());
        app.pending_attach = None;
        app.after_handover().unwrap();
        assert_eq!(app.screen, Screen::Ticket { ticket: t, rail_idx: 0 });

        // No worktree on the ticket: still the TICKET's terminal (T-366) —
        // the daemon puts it in the checkout, but it is this ticket's own,
        // so the ghost row, the preview and the adoption are about it and
        // never about the checkout's shared shell.
        app.worktrees.clear();
        sent.borrow_mut().clear();
        press(&mut app, '!');
        assert!(sent_contains(&sent, "OpenTerminal { ticket: Some("), "{:?}", sent.borrow());
        assert!(!sent_contains(&sent, "OpenTerminal { ticket: None }"), "{:?}", sent.borrow());
    }

    /// The terminal's ghost row (T-366): Enter arms, Enter again adopts,
    /// and any other key in between stands the arm down.
    #[test]
    fn enter_twice_adopts_the_terminal() {
        let (mut app, sent, _sid) = app_with_claude(SessionState::Running, false);
        let t = ulid::Ulid(1);
        app.terminals
            .push(mesimon_core::command::TerminalItem { ticket: Some(t), foreground: None });
        app.screen = Screen::Ticket { ticket: t, rail_idx: 1 };
        assert!(
            matches!(app.rail_row(), Some(RailRow::Terminal(_))),
            "the ghost row follows the session"
        );
        assert!(!app.terminal_busy(t));
        let before = sent.borrow().len();
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(sent.borrow().len(), before, "the first press only arms: {:?}", sent.borrow());
        assert_eq!(app.adopt_armed, Some(t));
        assert!(app.status.contains("enter again"), "{}", app.status);
        assert_eq!(
            keymap::hint_for(Scope::Ticket, Verb::Act, &app.ctx()).map(|(_, h)| h),
            Some("enter again adopts")
        );
        // A stray key stands it down.
        press(&mut app, 'k');
        assert!(app.adopt_armed.is_none());
        app.screen = Screen::Ticket { ticket: t, rail_idx: 1 };
        assert_eq!(
            keymap::hint_for(Scope::Ticket, Verb::Act, &app.ctx()).map(|(_, h)| h),
            Some("adopt shell")
        );
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent_contains(&sent, "AdoptTerminal"), "{:?}", sent.borrow());
        assert!(app.adopt_armed.is_none());
        // The card spins on a busy terminal, and the key that opens it goes
        // to the adopted shell once one is there.
        app.terminals[0].foreground = Some("cargo".into());
        assert!(app.terminal_busy(t));
    }

    /// `!` on a ticket that already has a shell session opens a FRESH
    /// terminal on the ticket (T-366, the user's rule): one more shell to
    /// adopt in turn, never a redirect to the one that is there. The hint
    /// keeps its word.
    #[test]
    fn bang_opens_another_terminal_beside_the_shell() {
        for state in [SessionState::Running, SessionState::Sleeping] {
            let (mut app, sent, _sid) = app_with_session(SessionKind::Bash, state, false);
            app.screen = Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 };
            assert_eq!(
                keymap::hint_for(Scope::Ticket, Verb::Terminal, &app.ctx()).map(|(_, h)| h),
                Some("terminal")
            );
            press(&mut app, '!');
            let log = sent.borrow().join("\n");
            assert!(log.contains("OpenTerminal { ticket: Some("), "{log}");
            assert!(!log.contains("FocusStart") && !log.contains("WakeSession"), "{log}");
        }
    }

    #[test]
    fn merge_replies_land_in_the_note_never_the_status() {
        // The m flow talks through the identity line's merge_note; the footer
        // (status) stays silent so the hint never doubles top + bottom.
        let mut app = app_three_columns();
        app.screen = Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 };
        press(&mut app, 'm'); // no worktree binding in the fixture
        assert_eq!(app.merge_note, "no worktree on this ticket");
        assert!(app.status.is_empty());
    }

    #[test]
    fn merge_refuses_up_front_while_the_agent_works() {
        // Quiet-tickets rule in the TUI: a mid-turn agent means the first m
        // refuses outright — never an armed confirm the daemon would bounce.
        let (mut app, sent, _sid) = app_with_claude(SessionState::Running, false);
        app.worktrees.push(WorktreeItem {
            ticket: ulid::Ulid(1),
            branch: "msmn/T-1-work".into(),
            status: "attached".into(),
            merged: false,
            merged_in: String::new(),
            merged_oid: String::new(),
            conflict: false,
            ahead: 2,
            needs_rebase: false,
            detail: None,
            path: None,
            repos: vec![],
        });
        app.screen = Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 };
        press(&mut app, 'm');
        assert_eq!(app.merge_note, "agent still working — wait for it to finish");
        assert!(app.merge_dialog.is_none(), "the flow never opens under a working agent");
        press(&mut app, 'm');
        assert!(!sent_contains(&sent, "MergeTicket"));
        // An idle agent lifts the gate: the first m opens the dialog as usual.
        app.board_mut().sessions[0].state =
            SessionState::Idle { stop_reason: mesimon_core::board::StopReason::EndTurn };
        press(&mut app, 'm');
        assert!(app.merge_dialog.is_some());
        assert_eq!(app.scope(), Scope::MergeChord);
    }

    #[test]
    fn merged_dialog_turns_into_the_notify_question_so_one_m_delivers() {
        // The post-merge dialog promises "m tells the agent" — that press must
        // notify, not re-open a confirm the dialog already gave (author
        // 2026-08-30). And the dialog never closes under the reader between
        // the merge landing and that press (T-431).
        let (mut app, sent, _sid) = app_with_claude(
            SessionState::Idle { stop_reason: mesimon_core::board::StopReason::EndTurn },
            false,
        );
        let wt = |merged, ahead| WorktreeItem {
            merged_in: String::new(),
            merged_oid: String::new(),
            ticket: ulid::Ulid(1),
            branch: "msmn/T-1-work".into(),
            status: "attached".into(),
            merged,
            conflict: false,
            ahead,
            needs_rebase: false,
            detail: None,
            path: None,
            repos: vec![],
        };
        app.worktrees.push(wt(false, 2));
        app.screen = Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 };
        press(&mut app, 'm'); // opens the dialog: "merge 2 commits of …?"
        assert_eq!(app.merge_dialog_rows()[0], "merge 2 commits of msmn/T-1-work?");
        assert_eq!(app.ctx().merge_confirm, "merge");
        assert!(!app.ctx().merge_actionable, "the row under the dialog stops offering");
        press(&mut app, 'm'); // confirms — sent detached, the dialog holds
        assert!(sent_contains(&sent, "MergeTicket"));
        assert!(app.merge_in_flight());
        assert_eq!(app.merge_dialog_rows()[0], "merging 2 commits of msmn/T-1-work…");
        assert_eq!(app.ctx().merge_confirm, "", "no key while git works");
        // Every key is held through the wait: not an answer, not a way out.
        press(&mut app, 'm');
        press(&mut app, 'q');
        assert!(app.merge_in_flight());
        assert!(!sent_contains(&sent, "MergedNotice"));
        // The reply lands on the tick: the dialog turns into the next question.
        assert!(app.poll_merge().unwrap());
        assert!(!app.merge_in_flight());
        let d = app.merge_dialog.as_ref().expect("the dialog stays up");
        assert_eq!(d.stage, MergeStage::Notify);
        assert_eq!(app.merge_dialog_rows()[0], "merged 2 commit(s)");
        assert_eq!(app.ctx().merge_confirm, "tell the agent");
        // The refresh's snapshot now carries the merged binding (the fake
        // transport returns none, so restore it by hand).
        app.worktrees.push(wt(true, 0));
        press(&mut app, 'm');
        assert!(sent_contains(&sent, "MergedNotice"), "one m after the merge notifies");
        assert_eq!(app.merge_note, "agent notified");
        assert!(app.merge_dialog.is_none());
    }

    /// T-613: a merge the board already told the agent about (a worker the
    /// crown started, the merged-notice pref on) has no second `m` to offer:
    /// the dialog closes, the identity line says why, and a later `m` reads
    /// the agent as told. A person's own worker (the test above) keeps the
    /// two steps.
    #[test]
    fn a_merge_that_told_the_agent_offers_no_second_press() {
        let (mut app, sent, _sid) = app_with_claude(
            SessionState::Idle { stop_reason: mesimon_core::board::StopReason::EndTurn },
            false,
        );
        let wt = |merged, ahead| WorktreeItem {
            merged_in: String::new(),
            merged_oid: String::new(),
            ticket: ulid::Ulid(1),
            branch: "msmn/T-1-work".into(),
            status: "attached".into(),
            merged,
            conflict: false,
            ahead,
            needs_rebase: false,
            detail: None,
            path: None,
            repos: vec![],
        };
        app.worktrees.push(wt(false, 2));
        app.screen = Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 };
        press(&mut app, 'm');
        press(&mut app, 'm');
        assert!(app.merge_in_flight());
        // The daemon's reply says the notice went with the merge.
        let (tx, rx) = std::sync::mpsc::channel();
        tx.send(Ok(Response::Merge {
            outcome: MergeOutcome::Merged,
            detail: "msmn/T-1-work merged into main".into(),
            notified: true,
        }))
        .unwrap();
        app.merge_dialog.as_mut().unwrap().running = Some(rx);
        assert!(app.poll_merge().unwrap());
        assert!(app.merge_dialog.is_none(), "no 'tell the agent' stage");
        assert_eq!(app.ctx().merge_confirm, "");
        assert_eq!(app.merge_note, "merged ∙ its agent was told");
        assert!(!sent_contains(&sent, "MergedNotice"), "the board sent it, not this press");
        // The snapshot now reads the branch merged: `m` says the agent was
        // told rather than asking blind.
        app.worktrees.push(wt(true, 0));
        assert_eq!(app.merge_outstanding(ulid::Ulid(1)), Some("agent notified"));
        press(&mut app, 'm');
        assert_eq!(app.ctx().merge_confirm, "tell it again");
        assert_eq!(app.merge_dialog_rows()[1], "the agent was told already — tell it again?");
    }

    #[test]
    fn esc_or_a_stray_key_closes_the_merge_dialog_and_says_so() {
        let (mut app, sent, _sid) = app_with_claude(
            SessionState::Idle { stop_reason: mesimon_core::board::StopReason::EndTurn },
            false,
        );
        app.worktrees.push(WorktreeItem {
            ticket: ulid::Ulid(1),
            branch: "msmn/T-1-work".into(),
            status: "attached".into(),
            merged: false,
            merged_in: String::new(),
            merged_oid: String::new(),
            conflict: false,
            ahead: 1,
            needs_rebase: false,
            detail: None,
            path: None,
            repos: vec![],
        });
        app.screen = Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 };
        press(&mut app, 'm');
        assert_eq!(app.merge_dialog_rows()[0], "merge 1 commit of msmn/T-1-work?");
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert!(app.merge_dialog.is_none());
        assert_eq!(app.status, "merge cancelled");
        assert_eq!(app.scope(), Scope::Ticket, "esc closes the dialog, not the page");
        press(&mut app, 'm');
        press(&mut app, 'j'); // a stray key cancels, the chord tails' rule
        assert!(app.merge_dialog.is_none());
        assert_eq!(app.status, "merge cancelled");
        assert!(!sent_contains(&sent, "MergeTicket"));
    }

    #[test]
    fn a_delivered_ask_is_not_offered_again_for_a_minute() {
        // "main moved ∙ m ask the agent to rebase" came straight back on the
        // next keypress after the agent had been asked (user 2026-09-03): the
        // note cleared and nothing else remembered the send. Now the delivery
        // holds the offer off for MERGE_ASK_COOLDOWN, longer while the agent
        // works, and lets go the moment the git state moves on.
        let (mut app, sent, _sid) = app_with_claude(
            SessionState::Idle { stop_reason: mesimon_core::board::StopReason::EndTurn },
            false,
        );
        let wt = || WorktreeItem {
            ticket: ulid::Ulid(1),
            branch: "msmn/T-1-work".into(),
            status: "attached".into(),
            merged: false,
            merged_in: String::new(),
            merged_oid: String::new(),
            conflict: false,
            ahead: 2,
            needs_rebase: true,
            detail: None,
            path: None,
            repos: vec![],
        };
        app.worktrees.push(wt());
        app.screen = Screen::Ticket { ticket: ulid::Ulid(1), rail_idx: 0 };
        assert_eq!(app.ctx().merge_word, "ask the agent to rebase");
        press(&mut app, 'm');
        press(&mut app, 'm');
        assert!(sent_contains(&sent, "Rebase"));
        assert_eq!(app.merge_note, "waiting for rebase");
        // The send's refresh took a snapshot the fake transport leaves empty;
        // main is still moved, so put the binding back.
        app.worktrees.push(wt());
        // The next keypress clears the note (`on_key`); the line says what
        // stands instead.
        app.on_key(KeyCode::Char('j'), KeyModifiers::NONE).unwrap();
        assert!(app.merge_note.is_empty());
        assert_eq!(app.merge_outstanding(ulid::Ulid(1)), Some("waiting for rebase"));
        assert!(!app.ctx().merge_actionable, "no offer while the ask is outstanding");
        // The key itself stays live, and the dialog says so instead of
        // asking blind.
        press(&mut app, 'm');
        assert_eq!(app.merge_dialog_rows()[1], "rebase already requested — ask the agent again?");
        assert_eq!(app.ctx().merge_confirm, "ask again");
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert_eq!(app.status, "rebase not asked");
        // A minute later, idle: offered again (main may have moved again).
        let (t, stage, _) = app.merge_sent.unwrap();
        app.merge_sent = Some((t, stage, Instant::now() - MERGE_ASK_COOLDOWN));
        assert_eq!(app.merge_outstanding(ulid::Ulid(1)), None);
        assert!(app.ctx().merge_actionable);
        // A minute later, still working on it: held.
        app.board_mut().sessions[0].state = SessionState::Running;
        assert_eq!(app.merge_outstanding(ulid::Ulid(1)), Some("waiting for rebase"));
        // The rebase landed: the stage moved on, so the record stops matching
        // at once, however fresh it is.
        app.merge_sent = Some((t, stage, Instant::now()));
        app.worktrees[0].needs_rebase = false;
        assert_eq!(app.merge_outstanding(ulid::Ulid(1)), None);
    }

    #[test]
