    /// A card a teammate moved keeps the cursor on it (T-335): the
    /// selection follows the ticket, not the row number.
    #[test]
    fn the_cursor_follows_its_ticket_across_a_remote_change() {
        let mut app = app_joined();
        app.cursor_col = 0;
        app.cursor_row = Some(1);
        assert_eq!(app.selected_ticket().map(|t| t.id), Some(ulid::Ulid(2)));
        // Elsewhere, ticket 2 moved to the top of todo, and then to doing.
        let mut board = board_three_columns();
        board.tickets[1].order = "0".into();
        app.absorb(Snapshot { board, ..Default::default() });
        assert_eq!((app.cursor_col, app.cursor_row), (0, Some(0)));
        assert_eq!(app.selected_ticket().map(|t| t.id), Some(ulid::Ulid(2)));
        let mut board = board_three_columns();
        board.tickets[1].column = "doing".into();
        app.absorb(Snapshot { board, ..Default::default() });
        assert_eq!((app.cursor_col, app.cursor_row), (1, Some(0)));
        assert_eq!(app.selected_ticket().map(|t| t.id), Some(ulid::Ulid(2)));
        // Gone: the cursor stays where it was and clamps.
        let mut board = board_three_columns();
        board.tickets.remove(1);
        app.absorb(Snapshot { board, ..Default::default() });
        assert_eq!(app.cursor_col, 1);
    }

    /// The boards section (T-335): the join row, then the boards; Enter on
    /// the join row opens the field, the code goes out on Enter, and the
    /// board the relay lists next is the one to open.
    #[test]
    fn joining_from_the_dialog_opens_the_board_the_relay_lists_next() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        app.team = super::joined_team_fixture();
        app.team.board = None;
        app.dispatch(Verb::Sharing, Key::Enter, Scope::Board, &app.ctx()).unwrap();
        let rows = app.sharing_rows();
        let join = rows.iter().position(|r| *r == SharingRow::Join).expect("join row");
        assert_eq!(rows.len(), join + 4, "three boards after the join row");
        let (label, _, word) = app.sharing_words(&rows[join + 1], false);
        assert_eq!((label.as_str(), word), ("mesimon ∙ contributor", "open"));
        let (label, detail, word) = app.sharing_words(&rows[join + 3], false);
        assert_eq!(label, "your board ∙ owner");
        assert!(detail.contains("checkout"), "{detail}");
        assert_eq!(word, "", "no copy here, nothing to open");
        // Enter on a board with a copy here leaves for that root.
        app.mode = Mode::Sharing { idx: join + 1, editing: None, armed: false };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.pending_switch.as_deref(), Some(Path::new("/state/team/boards/0b0b")));
        assert!(app.quit);
        app.quit = false;
        app.pending_switch = None;
        // The join row: Enter, a code, Enter.
        app.mode = Mode::Sharing { idx: join, editing: None, armed: false };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(matches!(app.mode, Mode::Sharing { editing: Some(_), .. }));
        assert_eq!(app.scope(), Scope::Input);
        for c in "7A3K-M9Q2".chars() {
            app.handle_key(KeyCode::Char(c), KeyModifiers::NONE).unwrap();
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(matches!(app.mode, Mode::Sharing { editing: None, .. }));
        assert!(sent.borrow().iter().any(|c| c.contains("JoinBoard") && c.contains("7A3K-M9Q2")));
        assert!(app.join_watch.is_some());
        // The daemon says joining; then the relay lists one more board.
        let mut team = super::joined_team_fixture();
        team.board = None;
        team.busy = Some("joining".into());
        app.absorb(Snapshot { board: board_three_columns(), team, ..Default::default() });
        assert_eq!(app.sharing_words(&SharingRow::Join, false).0, "Joining…");
        assert!(app.pending_switch.is_none());
        let mut team = super::joined_team_fixture();
        team.board = None;
        team.boards.push(mesimon_core::team::TeamBoardSummary {
            board: "0e".repeat(16),
            role: "contributor".into(),
            owner_name: "Kim".into(),
            root: Some(PathBuf::from("/state/team/boards/0e0e")),
            title: None,
        });
        app.absorb(Snapshot { board: board_three_columns(), team, ..Default::default() });
        assert_eq!(app.pending_switch.as_deref(), Some(Path::new("/state/team/boards/0e0e")));
        assert!(app.quit, "the main loop must leave for the exec to happen");
        assert!(app.join_watch.is_none());
    }

    /// A bad code comes back under the row and the watch is dropped: the
    /// next board the relay lists is not the one this code failed to join.
    #[test]
    fn a_failed_join_reads_on_the_row_and_opens_nothing() {
        let mut app = app_joined();
        app.team.board = None;
        let join = app.sharing_rows().iter().position(|r| *r == SharingRow::Join).unwrap();
        app.mode = Mode::Sharing { idx: join, editing: None, armed: false };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        for c in "nope".chars() {
            app.handle_key(KeyCode::Char(c), KeyModifiers::NONE).unwrap();
        }
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        let mut team = super::joined_team_fixture();
        team.board = None;
        team.error = Some("joining: not found".into());
        app.absorb(Snapshot { board: board_three_columns(), team, ..Default::default() });
        assert!(app.join_watch.is_none());
        assert!(app.pending_switch.is_none());
        let (_, detail, word) = app.sharing_words(&SharingRow::Join, false);
        assert_eq!(detail, "joining: not found ∙ enter tries again");
        assert_eq!(word, "join");
    }

    /// A member's board section ends in `Leave this board`, which arms on
    /// one press and sends on the second (T-335); the invite rows and
    /// `Stop sharing` are the owner's alone.
    #[test]
    fn a_member_leaves_from_the_sharing_dialog() {
        let (mut app, sent) = App::for_test_logged(board_three_columns(), theme(), false);
        app.team = super::joined_team_fixture();
        let rows = app.sharing_rows();
        let leave = rows.iter().position(|r| *r == SharingRow::Leave).expect("leave row");
        assert_eq!(rows[leave + 1], SharingRow::Heading("OTHER BOARDS"));
        // This board is the section above; the list under it is the rest.
        let current = SharingRow::Board(app.team.board.as_ref().expect("joined").board.clone());
        assert!(!rows.contains(&current));
        assert!(!rows.contains(&SharingRow::Unshare) && !rows.contains(&SharingRow::InviteViewer));
        app.mode = Mode::Sharing { idx: leave, editing: None, armed: false };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(matches!(app.mode, Mode::Sharing { armed: true, .. }));
        assert!(!sent.borrow().iter().any(|c| c.contains("LeaveBoard")));
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(sent.borrow().iter().any(|c| c.contains("LeaveBoard")));
        // The daemon answers: the board is no longer shared here.
        let mut team = super::joined_team_fixture();
        team.board = None;
        app.absorb(Snapshot { board: board_three_columns(), team, ..Default::default() });
        assert!(matches!(app.mode, Mode::Normal));
        assert!(app.status.contains("left the board"), "{}", app.status);
    }

    /// A note a teammate wrote while it is open here (T-335): the draft
    /// stays, the context row says who, and saving is still this draft.
    #[test]
    fn a_note_edited_elsewhere_keeps_the_draft_and_says_so() {
        let dir = std::env::temp_dir().join(format!("msmn-elsewhere-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let mut b = board_three_columns();
        b.tickets[0].notes.push(note_meta(90, 1, "local"));
        let sent = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let mut notes = std::collections::HashMap::new();
        notes.insert(ulid::Ulid(90), "the first draft".to_string());
        let fake = super::test_support::FakeTransport {
            board: b.clone(),
            grace: vec![],
            external: vec![],
            resources: Resources::default(),
            shell_env: Default::default(),
            git: Default::default(),
            pending: Vec::new(),
            automation: Default::default(),
            claude_md: Default::default(),
            status_top: false,
            sent: sent.clone(),
            refuse_focus: false,
            refuse_mint: false,
            notes,
            terminals: Vec::new(),
            machine_tiers: Default::default(),
            usage: Default::default(),
            clean_checkout: false,
        };
        let mut app = App::new(Box::new(fake), dir.clone(), theme()).unwrap();
        let mut team = super::joined_team_fixture();
        team.board.as_mut().unwrap().edited_elsewhere.clear();
        app.team = team;
        app.cursor_col = 0;
        app.cursor_row = Some(0);
        press(&mut app, 'n');
        let Mode::Editor(ed) = &app.mode else { panic!("{:?}", app.mode) };
        assert_eq!(ed.opened_rev, Some(1));
        assert!(app.note_changed_elsewhere(ed).is_none());
        for c in " and more".chars() {
            app.handle_key(KeyCode::Char(c), KeyModifiers::NONE).unwrap();
        }
        // Amit writes the note: rev 2, and the snapshot names him.
        let mut later = b.clone();
        later.tickets[0].notes[0].rev = 2;
        later.tickets[0].notes[0].edited_by = "member:Amit Ozalvo".into();
        let mut team = super::joined_team_fixture();
        team.board
            .as_mut()
            .unwrap()
            .edited_elsewhere
            .insert(ulid::Ulid(90).to_string(), "Amit Ozalvo".into());
        app.absorb(Snapshot { board: later, team, ..Default::default() });
        let Mode::Editor(ed) = &app.mode else { panic!("the draft was dropped: {:?}", app.mode) };
        let body = ed.body.as_str();
        assert!(body.contains("the first draft") && body.contains(" and more"), "{body}");
        assert_eq!(app.note_changed_elsewhere(ed).as_deref(), Some("Amit Ozalvo"));
        let _ = std::fs::remove_dir_all(&dir);
    }

    // ---- per-board overrides (T-361) ------------------------------------

    fn pref_scratch(name: &str) -> (PathBuf, PathBuf) {
        let dir =
            std::env::temp_dir().join(format!("msmn-boardprefs-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        (dir.join("prefs.json"), dir.join("proj").join("prefs.json"))
    }

    fn json(path: &std::path::Path) -> serde_json::Value {
        serde_json::from_str(&std::fs::read_to_string(path).unwrap_or_else(|_| "{}".into()))
            .unwrap()
    }

    /// `b` flips the scope, and Enter on the auto-merge row then cycles
    /// this board's override — on, off, inherit — in the BOARD file, while
    /// the machine file never learns of it. The daemon hears every step.
    #[test]
    fn b_flips_scope_and_enter_cycles_inherit_on_off_inherit() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        let (machine, board) = pref_scratch("cycle");
        // The machine's train off, so this board's cycle starts at on.
        app.seed_pref(|p| p.merge_train = false);
        app.prefs_path = Some(machine.clone());
        app.board_prefs_path = Some(board.clone());
        app.settings_section = keymap::SettingsSection::Behaviour;
        app.mode = Mode::Settings { idx: 0 };
        assert!(!app.settings_board_scope);
        app.handle_key(KeyCode::Char('b'), KeyModifiers::NONE).unwrap();
        assert!(app.settings_board_scope);
        assert!(app.ctx().pref_scope_offered);
        let row = app.settings_row(Verb::MergeTrain);
        app.mode = Mode::Settings { idx: row };
        let pushes = || sent.borrow().iter().filter(|c| c.contains("SetAutomation")).count();
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(app.prefs.merge_train, "resolved: on");
        assert!(!app.machine_prefs.merge_train, "the machine's copy is untouched");
        assert_eq!(json(&board)["merge_train"], true);
        assert!(json(&machine).get("merge_train").is_none(), "never written");
        assert!(app.status.contains("saved for this board"), "{}", app.status);
        assert_eq!(pushes(), 1);
        assert!(sent_contains(&sent, "SetAutomation { merge_train: true"));
        assert!(matches!(app.mode, Mode::Settings { .. }), "the list stays open");
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(!app.prefs.merge_train);
        assert_eq!(json(&board)["merge_train"], false);
        assert_eq!(pushes(), 2);
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(json(&board).get("merge_train").is_none(), "inherit: the key leaves the file");
        assert!(app.status.contains("inherits"), "{}", app.status);
        assert_eq!(pushes(), 3);
        // The detail says which it is, and `b` returns to the machine's.
        let ctx = app.ctx();
        assert!(ctx.pref_scope_board && ctx.board_overrides.is_empty());
        app.handle_key(KeyCode::Char('b'), KeyModifiers::NONE).unwrap();
        assert!(!app.settings_board_scope);
    }

    /// A machine row set AFTER a board override still writes the machine's
    /// own value: the resolved view is never what a save serialises.
    #[test]
    fn a_board_override_never_reaches_the_machine_file() {
        let (mut app, _, _) = app_with_claude(SessionState::Running, false);
        let (machine, board) = pref_scratch("leak");
        app.prefs_path = Some(machine.clone());
        app.board_prefs_path = Some(board);
        app.settings_board_scope = true;
        app.cycle_board_pref(PrefKey::KeepAwake);
        assert!(app.prefs.keep_awake);
        app.settings_board_scope = false;
        let ctx = app.ctx();
        app.dispatch(Verb::SnoozeQuiet, Key::Enter, Scope::Settings, &ctx).unwrap();
        let v = json(&machine);
        assert_eq!(v["keep_awake"], false, "{v}");
        assert_eq!(v["snooze_needs_you"], false);
        assert!(app.prefs.keep_awake, "and the override still holds");
    }

    /// A key the machine keeps is inert in board scope: the status says so
    /// and neither file moves.
    /// The Terminal rows (T-492): Enter cycles the title's shape and saves
    /// it; the words follow the board and the switches; a focus names the
    /// ticket while the follow row is on; the frame is empty while every
    /// row is off, and the iTerm2-only fields stay empty off iTerm2.
    #[test]
    fn the_terminal_rows_shape_the_tab_and_a_focus_names_the_ticket() {
        use crate::prefs::{TabColor, TabTitle};
        use crate::title::{Frame, Mark, Progress, Terminal};
        let (mut app, _, _) = app_with_claude(SessionState::Running, false);
        let (machine, _) = pref_scratch("tabtitle");
        app.prefs_path = Some(machine.clone());
        app.seed_pref(|p| {
            p.tab_title = TabTitle::Off;
            p.tab_title_needs_you = true;
            p.tab_theme = false;
            p.tab_color = TabColor::Off;
            p.tab_subtitle = false;
            p.tab_icon = false;
        });
        assert_eq!(app.tab_frame(false), Frame::default(), "everything off: nothing is written");
        app.settings_section = keymap::SettingsSection::Terminal;
        app.mode = Mode::Settings { idx: app.settings_row(Verb::TabTitle) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.prefs.tab_title, TabTitle::Project);
        let v: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&machine).unwrap()).unwrap();
        assert_eq!(v["tab_title"], "project");
        let board = app.board_name();
        assert_eq!(app.tab_title().unwrap(), board);
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.prefs.tab_title, TabTitle::Mesimon);
        assert_eq!(app.tab_title().unwrap(), format!("mesimon ∙ {board}"));
        // Nothing focused: the handover's title is the board's own.
        assert_eq!(app.focus_tab_title(), app.tab_title());
        let sid = app.board.sessions[0].id;
        let t = app.board.ticket(app.board.sessions[0].ticket).unwrap();
        let (key, title) = (t.short_key.clone(), t.title.clone());
        app.focused_session_hint = Some(FocusTarget::Session(sid, FocusOrigin::Board));
        assert_eq!(app.focus_tab_title().unwrap(), format!("mesimon ∙ {board} ∙ {key} {title}"));
        app.mode = Mode::Settings { idx: app.settings_row(Verb::TabTitleFocus) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(!app.prefs.tab_title_focus);
        assert_eq!(app.focus_tab_title(), app.tab_title(), "not following: the board's words");
        // The ring follows the agents; the iTerm2 fields need iTerm2.
        app.seed_pref(|p| {
            p.tab_progress = true;
            p.tab_color = TabColor::Dot;
            p.tab_subtitle = true;
        });
        let f = app.tab_frame(false);
        assert_eq!(f.progress, Some(Progress::Working));
        assert_eq!(f.mark, None, "not iTerm2");
        assert_eq!(f.subtitle, None);
        app.terminal = Terminal::ITerm2 { status: false };
        let f = app.tab_frame(false);
        assert_eq!(f.mark, None, "3.6: the dot's escape does not exist there");
        assert_eq!(f.subtitle, None);
        app.terminal = Terminal::ITerm2 { status: true };
        let f = app.tab_frame(false);
        assert_eq!(f.mark, Some(Mark::Off), "iTerm2 3.7, nothing needs you");
        assert_eq!(f.tint, None, "the theme row is off");
        assert_eq!(f.subtitle.as_deref(), Some("1 working"));
        assert_eq!(f.icon, None, "the row is off");
        app.seed_pref(|p| p.tab_icon = true);
        assert_eq!(app.tab_frame(false).icon, None, "on, but the files are not written yet");
        app.icons =
            Some(crate::title::Icons { resting: "/s/r.png".into(), needs_you: "/s/n.png".into() });
        assert_eq!(app.tab_frame(false).icon.as_deref(), Some(std::path::Path::new("/s/r.png")));
        app.mode = Mode::Settings { idx: app.settings_row(Verb::TabTitle) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.prefs.tab_title, TabTitle::Off, "the ring closes");
        assert_eq!(app.tab_title(), None);
    }

    /// The theme row (T-528): Enter saves it; the tab takes the hint
    /// line's colour on any iTerm2 (`OSC 6` is old) and nowhere else,
    /// follows a theme change, and yields to the needs-you whole-tab mark.
    #[test]
    fn the_theme_row_paints_the_tab_in_the_hint_line_colour() {
        use crate::title::{Mark, Terminal};
        let (mut app, _, _) = app_with_claude(SessionState::Running, false);
        let (machine, _) = pref_scratch("tabtheme");
        app.prefs_path = Some(machine.clone());
        app.seed_pref(|p| p.tab_theme = false);
        app.settings_section = keymap::SettingsSection::Terminal;
        app.mode = Mode::Settings { idx: app.settings_row(Verb::TabTheme) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(app.prefs.tab_theme);
        let v: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&machine).unwrap()).unwrap();
        assert_eq!(v["tab_theme"], true);
        assert_eq!(app.tab_frame(false).tint, None, "not iTerm2");
        app.terminal = Terminal::ITerm2 { status: false };
        let band = |app: &App| {
            let Some(ratatui::style::Color::Rgb(r, g, b)) = app.theme.selected_bg else {
                panic!("no band")
            };
            u32::from_be_bytes([0, r, g, b])
        };
        assert_eq!(app.tab_frame(false).tint, Some(band(&app)), "the hint line's colour");
        app.theme = Theme::new(Flavor::Blue, Profile::TrueColor);
        assert_eq!(app.tab_frame(false).tint, Some(band(&app)), "follows the theme");
        app.seed_pref(|p| p.tab_color = crate::prefs::TabColor::Tab);
        app.board_mut().tickets[0].woke_at = Some("@100".into());
        let f = app.tab_frame(false);
        let attn = Flavor::Blue.palette().truecolor.attn;
        assert_eq!((f.mark, f.tint), (Some(Mark::Tab(attn)), Some(band(&app))));
        app.mode = Mode::Settings { idx: app.settings_row(Verb::TabTheme) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.tab_frame(false).tint, None, "off");
    }

    /// Appearance opens in board scope (T-625), so its `(machine)` rows
    /// answer Enter on the machine's file rather than sit inert.
    #[test]
    fn a_machine_only_row_sets_the_machine_in_board_scope() {
        let (mut app, sent, _) = app_with_claude(SessionState::Running, false);
        let (machine, board) = pref_scratch("inert");
        app.prefs_path = Some(machine.clone());
        app.board_prefs_path = Some(board.clone());
        app.settings_section = keymap::SettingsSection::Appearance;
        app.settings_board_scope = true;
        app.mode = Mode::Settings { idx: app.settings_row(Verb::StatusLine) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(app.prefs.status_top);
        assert!(machine.exists() && !board.exists());
        assert!(sent_contains(&sent, "SetStatusLine"), "the daemon is told");
        assert!(app.settings_board_scope, "the list stays on this board");
    }

    /// The picker grows an inherit row first in board scope; Enter on a
    /// flavor sets the board's slot, Enter on inherit clears it, and the
    /// board rests on the machine's pick again.
    #[test]
    fn the_picker_has_an_inherit_row_in_board_scope() {
        let (mut app, _, _) = app_with_claude(SessionState::Running, false);
        let (machine, board) = pref_scratch("picker");
        app.prefs_path = Some(machine.clone());
        app.board_prefs_path = Some(board.clone());
        app.seed_pref(|p| p.set(Ground::Dark, Flavor::Graphite));
        app.settings_section = keymap::SettingsSection::Theme;
        app.settings_board_scope = true;
        assert_eq!(app.theme_rows(), Flavor::ALL.len() + 1);
        app.open_theme_picker();
        assert_eq!(
            app.mode,
            Mode::Theme { idx: 0, slot: Slot::Both },
            "opens on inherit while nothing is set"
        );
        assert_eq!(app.theme_at(0), None);
        let blue = Flavor::ALL.iter().position(|f| *f == Flavor::Blue).unwrap() + 1;
        app.mode = Mode::Theme { idx: blue, slot: Slot::One(Ground::Dark) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_eq!(app.prefs.dark, Flavor::Blue);
        assert_eq!(app.machine_prefs.dark, Flavor::Graphite);
        assert_eq!(json(&board)["dark"], "blue");
        assert!(json(&machine).get("dark").is_none());
        assert_eq!(app.theme.flavor, Flavor::Blue);
        // Reopen: the cursor sits on the board's pick, one past inherit.
        app.open_theme_picker();
        assert_eq!(app.mode, Mode::Theme { idx: blue, slot: Slot::Both });
        app.mode = Mode::Theme { idx: 0, slot: Slot::One(Ground::Dark) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert!(json(&board).get("dark").is_none(), "inherit drops the slot");
        assert_eq!(app.prefs.dark, Flavor::Graphite);
        assert_eq!(app.theme.flavor, Flavor::Graphite, "the board rests on the machine's");
        // Machine scope: the picker is the six rows it always was.
        app.settings_board_scope = false;
        assert_eq!(app.theme_rows(), Flavor::ALL.len());
        assert_eq!(app.theme_at(0), Some(Flavor::ALL[0]));
    }

    /// Opening Settings from the menu always lands in machine scope, and
    /// `b` is offered on exactly the sections with a row a board can set
    /// (T-361, T-443): Theme, Appearance, Notifications, Behaviour, Agents.
    #[test]
    fn opening_settings_resets_the_scope() {
        let (mut app, _, _) = app_with_claude(SessionState::Running, false);
        app.settings_board_scope = true;
        let ctx = app.ctx();
        app.dispatch(Verb::Settings, Key::Enter, Scope::Menu, &ctx).unwrap();
        assert!(!app.settings_board_scope);
        let mut offered = Vec::new();
        for section in keymap::SettingsSection::ALL {
            assert_eq!(app.settings_section, section);
            if app.ctx().pref_scope_offered {
                offered.push(section);
            }
            press(&mut app, 'j');
        }
        use keymap::SettingsSection as S;
        assert_eq!(offered, [S::Theme, S::Appearance, S::Notifications, S::Behaviour, S::Agents]);
    }

    /// The scope is the dialog's (T-717): `b` on a page flips it, it holds
    /// while the section list moves, a row the machine keeps still sets the
    /// machine's, and leaving the dialog drops it — as does the Usage
    /// dialog's `s`, which opens Settings straight from the menu.
    #[test]
    fn the_scope_holds_across_sections_and_leaves_with_the_dialog() {
        let (mut app, _, _) = app_with_claude(SessionState::Running, false);
        let (machine, board) = pref_scratch("leave");
        app.prefs_path = Some(machine.clone());
        app.board_prefs_path = Some(board.clone());
        open_section(&mut app, keymap::SettingsSection::Appearance);
        press(&mut app, 'b');
        assert!(app.settings_board_scope);
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert_eq!(app.mode, Mode::Sections);
        assert!(app.settings_board_scope, "the list keeps the page's scope");
        while app.settings_section != keymap::SettingsSection::Terminal {
            press(&mut app, 'j');
        }
        assert!(!app.ctx().pref_scope_offered, "no row here is a board's");
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        let before = app.prefs.tab_title;
        app.mode = Mode::Settings { idx: app.settings_row(Verb::TabTitle) };
        app.handle_key(KeyCode::Enter, KeyModifiers::NONE).unwrap();
        assert_ne!(app.prefs.tab_title, before, "a machine row acts, on the machine's");
        assert!(machine.exists() && !board.exists());
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        assert!(matches!(app.mode, Mode::Menu { .. }));
        assert!(!app.settings_board_scope, "out of the dialog, out of the scope");
        // `,` opens it from the board, on the machine's settings.
        app.handle_key(KeyCode::Esc, KeyModifiers::NONE).unwrap();
        app.settings_board_scope = true;
        press(&mut app, ',');
        assert_eq!(app.mode, Mode::Sections);
        assert!(!app.settings_board_scope);
    }
    fn queued_picture(
        app: &mut App,
        result: std::result::Result<crate::image_paste::Pasted, String>,
    ) {
        let ed = editor(app);
        let (tx, rx) = std::sync::mpsc::channel();
        app.pending_paste = Some(crate::image_paste::Pending {
            started: Instant::now(),
            timed_out: false,
            editor: ed.draft_id,
            body: ed.body.clone(),
            result: rx,
        });
        tx.send(result).unwrap();
    }

    #[test]
    fn pictures_insert_at_the_cursor_and_save_as_links_without_showing_ids() {
        let (mut app, sent) = app_with_note();
        app.open_note_editor(ulid::Ulid(1), None).unwrap();
        app.on_paste("before after").unwrap();
        if let Mode::Editor(ed) = &mut app.mode {
            for _ in 0..5 {
                ed.body.left();
            }
        }
        queued_picture(&mut app, Ok(crate::image_paste::Pasted::Image(vec![1, 2, 3])));
        assert!(app.poll_image_paste());
        assert_eq!(editor(&app).body.as_str(), "before [Image #1]after");
        assert!(editor(&app).dirty());
        let ed = editor(&app).clone();
        app.editor_save(ed).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(sent
            .borrow()
            .iter()
            .any(|c| c.contains("SaveNoteWithAttachments") && c.contains("mesimon-attachment:")));
        let body = app
            .notes
            .values()
            .filter_map(|n| n.text.as_deref())
            .find(|b| b.contains("mesimon-attachment:"))
            .unwrap();
        let (plain, refs) = crate::image_paste::unpack(body);
        assert_eq!(plain, "before [Image #1]after");
        assert_eq!(refs.len(), 1);
    }

    #[test]
    fn stale_clipboard_results_cannot_change_another_editor_or_a_changed_body() {
        let (mut app, _) = app_with_note();
        app.open_note_editor(ulid::Ulid(1), None).unwrap();
        queued_picture(&mut app, Ok(crate::image_paste::Pasted::Image(vec![1])));
        app.open_note_editor(ulid::Ulid(1), None).unwrap();
        assert!(!app.poll_image_paste());
        assert!(editor(&app).images.is_empty());
        queued_picture(&mut app, Ok(crate::image_paste::Pasted::Image(vec![1])));
        app.on_paste("typed meanwhile").unwrap();
        assert!(app.poll_image_paste());
        assert_eq!(editor(&app).body.as_str(), "typed meanwhile");
        assert!(editor(&app).images.is_empty());
        assert!(app.status.contains("paste again"));
    }

    #[test]
    fn image_paste_errors_and_note_limit_do_not_insert_partial_markers() {
        let (mut app, _) = app_with_note();
        app.open_note_editor(ulid::Ulid(1), None).unwrap();
        queued_picture(&mut app, Err("clipboard unavailable".into()));
        app.poll_image_paste();
        assert!(editor(&app).body.as_str().is_empty());
        assert_eq!(app.status, "clipboard unavailable");
        app.on_paste(&"x".repeat(mesimon_core::board::NOTE_MAX_BYTES - 5)).unwrap();
        let before = editor(&app).body.clone();
        queued_picture(&mut app, Ok(crate::image_paste::Pasted::Image(vec![1])));
        app.poll_image_paste();
        assert_eq!(editor(&app).body, before);
        assert!(editor(&app).images.is_empty());
    }

    #[test]
    fn composer_folding_keeps_images_and_discard_does_not_upload() {
        let (mut app, sent) = app_with_note();
        app.mode = Mode::Editor(Editor::new(
            EditorPurpose::Compose { workspace: None, tags: vec![], plan: false, tier: None },
            EditBuffer::from_text("new ticket".into(), mesimon_core::board::TITLE_MAX_BYTES),
            TextArea::new(mesimon_core::board::NOTE_MAX_BYTES),
            Field::Body,
        ));
        queued_picture(&mut app, Ok(crate::image_paste::Pasted::Image(vec![1, 2])));
        app.poll_image_paste();
        let ed = editor(&app).clone();
        app.editor_save(ed).unwrap();
        let Mode::Input { purpose, buffer } = app.mode.clone() else { panic!("composer folded") };
        let InputPurpose::Create { images, .. } = &purpose else { panic!() };
        assert_eq!(images[0].png.as_deref(), Some(&[1, 2][..]));
        assert!(!sent.borrow().iter().any(|s| s.contains("UploadAttachment")));
        app.commit_input(purpose, buffer.into_text(), false).unwrap();
        assert!(sent.borrow().iter().any(|s| s.contains("CreateTicketWithNote")));
        app.open_note_editor(ulid::Ulid(1), None).unwrap();
        queued_picture(&mut app, Ok(crate::image_paste::Pasted::Image(vec![3])));
        app.poll_image_paste();
        sent.borrow_mut().clear();
        app.editor_cancel(editor(&app).clone()).unwrap();
        app.editor_cancel(editor(&app).clone()).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        assert!(!sent.borrow().iter().any(|s| s.contains("UploadAttachment")));
    }

    #[test]
    fn failed_image_save_keeps_the_draft_and_retry_succeeds() {
        struct FailOnce {
            inner: Box<dyn Transport>,
            failed: bool,
        }
        impl Transport for FailOnce {
            fn request(&mut self, command: Command) -> Result<Response> {
                if !self.failed && matches!(command, Command::SaveNoteWithAttachments { .. }) {
                    self.failed = true;
                    return Ok(Response::Err { message: "disk full".into() });
                }
                self.inner.request(command)
            }
            fn poll_event(&mut self) -> bool {
                false
            }
        }
        let (mut app, sent) = app_with_note();
        app.client = Box::new(FailOnce { inner: app.client, failed: false });
        app.open_note_editor(ulid::Ulid(1), None).unwrap();
        queued_picture(&mut app, Ok(crate::image_paste::Pasted::Image(vec![1])));
        app.poll_image_paste();
        app.editor_save(editor(&app).clone()).unwrap();
        assert_eq!(app.status, "disk full");
        assert!(editor(&app).images[0].png.is_some());
        assert!(editor(&app).dirty());
        assert!(sent.borrow().iter().any(|s| s.contains("DiscardAttachmentUploads")));
        app.editor_save(editor(&app).clone()).unwrap();
        assert_eq!(app.mode, Mode::Normal);
    }
    #[test]
    fn timed_out_clipboard_reads_do_not_block_save_or_apply_late_results() {
        let (mut app, _) = app_with_note();
        app.open_note_editor(ulid::Ulid(1), None).unwrap();
        let ed = editor(&app).clone();
        let (tx, result) = std::sync::mpsc::channel();
        app.pending_paste = Some(crate::image_paste::Pending {
            editor: ed.draft_id,
            body: ed.body.clone(),
            result,
            started: Instant::now() - Duration::from_secs(4),
            timed_out: false,
        });
        assert!(app.poll_image_paste());
        assert!(app.status.contains("timed out"));
        app.editor_save(ed).unwrap();
        assert_eq!(app.mode, Mode::Normal);
        tx.send(Ok(crate::image_paste::Pasted::Image(vec![1]))).unwrap();
        assert!(!app.poll_image_paste());
        assert!(app.pending_paste.is_none());
    }

    #[test]
    fn clipboard_text_paste_keeps_newlines_and_never_saves() {
        let (mut app, sent) = app_with_note();
        app.open_note_editor(ulid::Ulid(1), None).unwrap();
        queued_picture(&mut app, Ok(crate::image_paste::Pasted::Text("one\r\ntwo\n".into())));
        assert!(app.poll_image_paste());
        assert_eq!(editor(&app).body.as_str(), "one\ntwo\n");
        assert!(!sent.borrow().iter().any(|s| s.contains("WriteNote")));
    }
